(function () {
  var MAJOR = 'medicine-药学';
  var ov = MAJOR_STAGE_OVERRIDES[MAJOR];
  if (!ov) return;

  var EXTRA = {
    '无机化学': [
      { title: '酸碱平衡与缓冲溶液', brief: '质子理论、pH 计算与缓冲容量。',
        q: [
          { stem: '按酸碱质子理论，下列物质中属于两性物质的是：', options: ['H2O', 'HCl', 'NaOH', 'NaCl'], answer: 0, explain: '水既能给出质子又能接受质子，是典型的两性物质；HCl 是酸，NaOH 是碱。' },
          { stem: '0.1 mol/L 氨水（Kb=1.8×10^-5）的 pH 约为：', options: ['8.9', '11.1', '7.0', '12.5'], answer: 1, explain: '由 [OH-]=√(Kb·c) 得约 1.34×10^-3 mol/L，pOH 约 2.9，故 pH 约 11.1。' },
          { stem: '缓冲溶液的缓冲容量达到最大的条件是：', options: ['pH = pKa + 2', 'pH = 7', 'pH = pKa', 'pH = 14'], answer: 2, explain: '共轭酸碱组分量相等即 pH = pKa 时，抗酸抗碱能力最强，缓冲容量最大。' }
        ],
        doc: { lead: '酸碱质子理论把酸碱统一为质子的给出与接受，缓冲溶液则是对抗 pH 变化的定量工具。', sections: [
          { id: 'k1', title: '质子理论与 pH', html: `<p>酸碱质子理论认为，凡能给出质子的分子或离子都是酸，凡能接受质子的都是碱，酸给出质子后形成的碱称为共轭碱，二者组成共轭酸碱对，彼此只相差一个质子。</p><p>共轭酸碱对的 Ka 与 Kb 之积等于水的离子积 Kw，因此酸越强其共轭碱越弱。25 ℃ 时 Kw 为 1.0×10^-14，据此可由 Ka 求共轭碱的 Kb，也可比较不同弱酸的相对强弱，并计算弱酸弱碱溶液的 pH。</p>` },
          { id: 'k2', title: '缓冲溶液', html: `<p>缓冲溶液通常由弱酸及其共轭碱或弱碱及其共轭酸组成，能抵抗外加少量强酸、强碱或稀释对 pH 的影响。按 Henderson-Hasselbalch 方程，pH = pKa + lg([A-]/[HA])，当组分量相等时 pH 等于 pKa。</p><p>缓冲容量在 pH = pKa 时最大，有效缓冲范围约为 pKa±1。血液依靠 H2CO3/HCO3- 缓冲对维持 pH 在 7.35～7.45，药物制剂也常用磷酸盐、柠檬酸盐缓冲对稳定 pH。</p><ul><li>缓冲对选择应使 pKa 接近目标 pH。</li><li>缓冲容量与总浓度和组分配比有关。</li></ul>` }
        ], refs: [] } },
      { title: '沉淀溶解平衡', brief: '溶度积、同离子效应与分步沉淀。',
        q: [
          { stem: 'AgCl 的溶度积表达式是：', options: ['[Ag+][Cl-]', '[AgCl]/([Ag+][Cl-])', '[Ag+]/[Cl-]', '[AgCl]'], answer: 0, explain: 'AgCl 溶解生成等量 Ag+ 与 Cl-，其 Ksp 为两种离子浓度的乘积。' },
          { stem: '向 AgCl 饱和溶液中加入 NaCl，AgCl 的溶解度将：', options: ['增大', '减小', '不变', '先增后减'], answer: 1, explain: '同离子效应使溶解平衡左移，AgCl 溶解度降低。' },
          { stem: '溶液中 Cl- 与 I- 浓度相同，逐滴加入 AgNO3 时先沉淀的是：', options: ['AgCl', '两者同时', 'AgI', '无法判断'], answer: 2, explain: 'AgI 的 Ksp 更小，达到溶度积所需的 Ag+ 浓度更低，故先沉淀。' }
        ],
        doc: { lead: '沉淀溶解平衡用溶度积判断生成与溶解，同离子效应和分步沉淀是常见应用。', sections: [
          { id: 'k1', title: '溶度积与溶解度', html: `<p>难溶电解质的溶解平衡可用溶度积 Ksp 描述，AgCl 的 Ksp 等于 [Ag+][Cl-]。Ksp 只随温度变化，与溶液中离子浓度无关，是衡量难溶盐溶解能力的常数。</p><p>溶解度与 Ksp 可相互换算，但只有同类型难溶盐才能直接比较 Ksp 大小。加入含有相同离子的强电解质会产生同离子效应，使溶解平衡左移、溶解度降低，这一规律在药物沉淀分离中经常用到。</p>` },
          { id: 'k2', title: '沉淀的生成与转化', html: `<p>将溶液离子积 J 与 Ksp 比较可判断沉淀是否生成：J 大于 Ksp 时生成沉淀，等于时达到饱和，小于时沉淀溶解。调节 pH、加入配位剂或氧化还原剂都能使沉淀溶解。</p><p>当溶液中多种离子都能与同一沉淀剂反应时，J 先达到 Ksp 的离子先沉淀，称为分步沉淀。沉淀也可由溶解度更小的沉淀转化而来，如 AgCl 遇 I- 转化为 AgI，药物分析中的沉淀滴定即以此为基础。</p><ul><li>洗涤沉淀可减少表面吸附杂质。</li><li>陈化可使沉淀颗粒变大、易于过滤。</li></ul>` }
        ], refs: [] } },
      { title: '氧化还原与电化学', brief: '氧化数、原电池与 Nernst 方程。',
        q: [
          { stem: '原电池中发生氧化反应的电极是：', options: ['正极', '负极', '盐桥', '参比电极'], answer: 1, explain: '原电池负极失去电子发生氧化，正极得到电子发生还原。' },
          { stem: '标准氢电极的电极电势规定为：', options: ['0 V', '1 V', '-1 V', '0.5 V'], answer: 0, explain: '标准氢电极是电极电势的参比基准，其标准电极电势规定为 0 V。' },
          { stem: '电极电势越高，说明该电对氧化型得电子能力：', options: ['越弱', '不变', '越强', '无法判断'], answer: 2, explain: '电极电势越高，氧化型越易得电子被还原，氧化能力越强。' }
        ],
        doc: { lead: '氧化还原反应的本质是电子转移，电极电势把这种转移倾向量化。', sections: [
          { id: 'k1', title: '氧化数与配平', html: `<p>氧化还原反应的本质是电子转移，元素氧化数升高为氧化、降低为还原。氧化剂自身被还原，还原剂自身被氧化，氧化与还原总是同时发生。</p><p>配平氧化还原方程式时，先确定氧化数变化并配平电子转移数，再配平原子与电荷，最后检查氢和氧。酸性、碱性介质中补 H+、OH- 和 H2O 的方式不同，需按介质条件处理，配平后还应复核电子守恒与电荷守恒。</p>` },
          { id: 'k2', title: '原电池与 Nernst 方程', html: `<p>原电池把化学能转化为电能，负极发生氧化反应，正极发生还原反应，盐桥用于导通离子并维持电中性。电池电动势等于正极电势减负极电势，正值表示反应可自发进行。</p><p>Nernst 方程把电极电势与标准电极电势、反应物浓度和温度联系起来。电极电势越高，氧化型得电子能力越强；改变浓度或温度会改变电极电势，从而影响氧化还原反应的方向。</p><ul><li>标准电极电势表可用于判断氧化剂还原剂的相对强弱。</li><li>电动势为正时反应自发，为负时逆向进行。</li></ul>` }
        ], refs: [] } },
      { title: '配位化合物', brief: '组成、命名、稳定常数与螯合效应。',
        q: [
          { stem: '配合物的配位数是指：', options: ['配体分子总数', '中心离子的电荷数', '中心离子直接结合的配位原子数', '配合物的总电荷'], answer: 2, explain: '配位数是中心离子直接结合的配位原子数目，不是配体分子数。' },
          { stem: '下列配体中最易与金属离子形成螯合物的是：', options: ['NH3', 'Cl-', 'EDTA', 'H2O'], answer: 2, explain: 'EDTA 为多齿配体，可与同一中心离子形成多个配位键和环状结构，螯合效应显著。' },
          { stem: '配合物稳定常数越大，说明：', options: ['配合物越稳定', '配体数目越少', '中心离子电荷越低', '溶解度越大'], answer: 0, explain: '稳定常数是生成反应的平衡常数，数值越大表示配合物越易生成、越稳定。' }
        ],
        doc: { lead: '配合物由中心离子与配体通过配位键组成，稳定常数与螯合效应决定其稳定性。', sections: [
          { id: 'k1', title: '组成与命名', html: `<p>配合物由中心离子或原子、配体和外界离子组成，配体提供孤对电子，中心离子提供空轨道，二者以配位键结合。直接与中心离子结合的配位原子数目称为配位数。</p><p>命名时先命名配体、后命名中心离子，配体数目用二、三、四标明，中心离子的氧化数用罗马数字写在括号内。配离子为阴离子时，中心离子名称后加“酸”字，如六氰合铁(II)酸钾。</p>` },
          { id: 'k2', title: '稳定常数与配位平衡', html: `<p>配合物的稳定性用稳定常数衡量，稳定常数越大，配合物越易生成、越稳定。逐级稳定常数相乘得到总稳定常数，可用于计算配位平衡中各组分的浓度。</p><p>多齿配体与同一中心离子形成环状螯合物，五元环和六元环最稳定，这种额外稳定性称为螯合效应。EDTA 是常用六齿配体，能与多数金属离子形成稳定螯合物，广泛用于配位滴定和重金属解毒。</p><ul><li>加酸可使配体质子化，破坏配位平衡。</li><li>加入沉淀剂或氧化还原剂也会使配位平衡移动。</li><li>四环素与钙、镁离子结合会影响吸收。</li></ul>` }
        ], refs: [] } }
    ],

    '有机化学': [
      { title: '烷烃与自由基取代', brief: '构象、自由基稳定性与卤代反应。',
        q: [
          { stem: '乙烷最稳定的构象是：', options: ['交叉式', '重叠式', '半重叠式', '平面式'], answer: 0, explain: '交叉式中两个甲基相距最远，扭转张力最小，能量最低。' },
          { stem: '烷基自由基稳定性由大到小的顺序是：', options: ['伯 > 仲 > 叔', '叔 > 仲 > 伯', '仲 > 叔 > 伯', '三者相同'], answer: 1, explain: '烷基供电子和超共轭效应稳定自由基，故叔自由基最稳定。' },
          { stem: '甲烷与氯气发生取代反应的条件是：', options: ['避光冷藏', '强酸催化', '光照或加热', '加入还原剂'], answer: 2, explain: '甲烷氯代是自由基取代反应，需光照或加热引发氯分子均裂。' }
        ],
        doc: { lead: '烷烃的化学性质以自由基取代为主，构象和自由基稳定性决定反应选择性。', sections: [
          { id: 'k1', title: '构象', html: `<p>乙烷沿碳碳单键旋转可形成交叉式和重叠式构象，交叉式中两个甲基相距最远，扭转张力最小，能量最低。丁烷还有反式与邻位交叉式，反式最稳定。</p><p>环己烷以椅式构象最稳定，椅式没有船式的旗杆氢排斥；取代基优先占据平伏键，以减少与直立键氢的 1,3-二直立键排斥，大基团尤其如此。构象分析是理解反应立体化学的基础。</p>` },
          { id: 'k2', title: '自由基取代', html: `<p>烷烃卤代属自由基取代，反应经链引发、链增长和链终止三个阶段。光照或加热使卤素分子均裂产生自由基，进而夺取烷烃氢原子生成烷基自由基。</p><p>自由基稳定性顺序为叔大于仲大于伯，因此卤代优先发生在叔碳上。卤素活性为氟大于氯大于溴大于碘，溴代选择性最高，碘代最难进行；产物常为混合物，合成中需考虑选择性。</p><ul><li>链引发产生自由基，链增长消耗原料并生成产物。</li><li>两个自由基结合即链终止。</li></ul>` }
        ], refs: [] } },
      { title: '烯烃与炔烃', brief: '亲电加成、马氏规则与氧化反应。',
        q: [
          { stem: '丙烯与溴化氢加成的主要产物是：', options: ['1-溴丙烷', '2-溴丙烷', '1,2-二溴丙烷', '丙醇'], answer: 1, explain: '按马氏规则，氢加到含氢较多的双键碳上，溴加到含氢较少的碳上，主产物为 2-溴丙烷。' },
          { stem: '烯烃使溴水褪色，说明发生了：', options: ['取代反应', '聚合反应', '加成反应', '消去反应'], answer: 2, explain: '溴与碳碳双键发生亲电加成，消耗溴而使溴水褪色。' },
          { stem: '可用于鉴别末端炔烃的试剂是：', options: ['银氨溶液', '溴水', '高锰酸钾', '氯化钠'], answer: 0, explain: '末端炔烃的炔氢可被银氨溶液取代，生成白色炔银沉淀。' }
        ],
        doc: { lead: '烯烃和炔烃的不饱和键是亲电加成和氧化的反应中心。', sections: [
          { id: 'k1', title: '亲电加成与马氏规则', html: `<p>烯烃的碳碳双键易发生亲电加成，卤素、卤化氢、水和硫酸均可加成。反应经较稳定的碳正离子中间体，故氢加到含氢较多的双键碳上，这就是马氏规则。</p><p>碳正离子可发生重排，使产物超出马氏规则的简单预测；在过氧化物存在下，HBr 与烯烃发生反马氏加成，经自由基机理进行，这是马氏规则的重要例外。</p><ul><li>马氏规则的本质是中间体碳正离子的稳定性。</li><li>过氧化物效应只对 HBr 明显。</li></ul>` },
          { id: 'k2', title: '氧化与聚合', html: `<p>烯烃可被冷稀高锰酸钾氧化为邻二醇，使紫红色褪去，可用于鉴别不饱和键；酸性高锰酸钾可断裂双键，生成羧酸或酮。臭氧化还原水解也能确定双键位置。</p><p>炔烃可进行加成、氧化和聚合反应，完全氢化生成烷烃。末端炔烃与银氨溶液生成白色炔银沉淀，可用于鉴别；炔烃加聚和环加成在合成中也有应用。</p><ul><li>烯烃加聚生成高分子，是塑料工业的基础。</li><li>炔烃可加两分子氢，也可选择性部分加氢。</li></ul>` }
        ], refs: [] } },
      { title: '芳香烃', brief: '芳香性、亲电取代与定位效应。',
        q: [
          { stem: '苯分子中参与共轭的 π 电子数为：', options: ['4', '5', '6', '8'], answer: 2, explain: '苯为平面闭合共轭体系，6 个 π 电子符合 4n+2 规则，具有芳香性。' },
          { stem: '硝基苯发生亲电取代时，新取代基主要进入：', options: ['邻位', '对位', '邻对位', '间位'], answer: 3, explain: '硝基是强吸电子基团，属间位定位基，使苯环钝化但导向间位。' },
          { stem: '甲苯发生硝化反应时，新取代基主要进入：', options: ['邻位和对位', '间位', '仅对位', '仅邻位'], answer: 0, explain: '甲基是给电子基团，属邻对位定位基，使苯环活化。' }
        ],
        doc: { lead: '芳香性由闭合共轭和 4n+2 规则决定，取代基决定亲电取代的定位和活性。', sections: [
          { id: 'k1', title: '芳香性', html: `<p>苯是平面正六边形分子，六个碳均为 sp2 杂化，未参与杂化的 p 轨道侧面重叠形成闭合共轭体系，π 电子离域使苯具有特殊稳定性，称为芳香性。</p><p>休克尔规则指出，平面、闭合共轭且 π 电子数为 4n+2 的体系具有芳香性，n 取 0、1、2 等整数。萘、蒽、菲等稠环芳烃以及吡啶、呋喃等杂环也符合这一规律。芳香性使苯环不易发生加成反应，而倾向于亲电取代。</p>` },
          { id: 'k2', title: '亲电取代与定位', html: `<p>苯环的典型反应是亲电取代，包括硝化、卤代、磺化和傅克烷基化、酰基化。取代基按定位效应分为邻对位定位基和间位定位基，前者多为给电子基，后者多为吸电子基。</p><p>卤素是钝化苯环但导向邻对位的例外。烷基苯的侧链可被酸性高锰酸钾氧化为羧酸，含 α-氢时反应发生；不含 α-氢的叔丁基苯则不能被氧化。</p><ul><li>强活化基团可发生多取代。</li><li>傅克反应需无水条件，易发生重排。</li></ul>` }
        ], refs: [] } },
      { title: '醛酮与羧酸衍生物', brief: '亲核加成、羟醛缩合与酰基取代。',
        q: [
          { stem: '能发生银镜反应的化合物是：', options: ['丙酮', '乙醇', '乙酸', '乙醛'], answer: 3, explain: '醛基可被银氨溶液氧化生成银镜，酮和羧酸不能发生该反应。' },
          { stem: '羟醛缩合反应的必要条件是：', options: ['醛或酮具有 α-氢', '分子中必须有苯环', '必须无 α-氢', '必须在酸性条件下'], answer: 0, explain: '碱催化下 α-氢被夺去形成烯醇负离子，再进攻另一分子羰基，故需 α-氢。' },
          { stem: '酯在碱性条件下的水解属于：', options: ['亲电加成', '亲核酰基取代', '自由基取代', '消去反应'], answer: 1, explain: '氢氧根作为亲核试剂进攻羰基碳，经四面体中间体发生酰氧键断裂。' }
        ],
        doc: { lead: '羰基是亲核加成的中心，羧酸衍生物则通过酰基取代相互转化。', sections: [
          { id: 'k1', title: '醛酮', html: `<p>醛酮的羰基碳带部分正电荷，易受亲核试剂进攻，发生亲核加成、缩合和还原反应。醛可被银氨溶液氧化生成银镜，也可还原斐林试剂，酮一般不能，这是鉴别醛酮的重要依据。</p><p>甲基酮和含 CH3CH(OH)- 结构的醇可发生碘仿反应，生成黄色碘仿沉淀。含 α-氢的醛酮在碱催化下发生羟醛缩合，形成新的碳碳键，是合成中增长碳链的重要方法。</p>` },
          { id: 'k2', title: '羧酸衍生物', html: `<p>羧酸衍生物包括酰卤、酸酐、酯和酰胺，水解活性依次降低。它们都发生亲核酰基取代，亲核试剂进攻羰基碳，经四面体中间体后离去基团脱落。</p><p>酸催化酯化多为酰氧键断裂，羧酸脱羟基、醇脱氢，反应可逆，需移除水促进平衡右移。酰胺水解需较强条件，是蛋白质水解的基础；药物分子中的酯键易水解，酰胺键相对稳定。</p><ul><li>酰卤活性最高，常用于制备其他衍生物。</li><li>羧酸衍生物可相互转化，活性高者转为活性低者。</li></ul>` }
        ], refs: [] } }
    ],

    '药学导论': [
      { title: '剂型与给药途径', brief: '常见剂型、首过效应与生物利用度。',
        q: [
          { stem: '舌下含服给药的主要优点是：', options: ['避免肝首过效应', '吸收最慢', '剂量最大', '只能用于急救'], answer: 0, explain: '舌下黏膜血流丰富，药物直接进入体循环，可避开胃肠道和肝首过效应。' },
          { stem: '下列给药途径中，生物利用度可视为 100% 的是：', options: ['口服', '静脉注射', '直肠给药', '透皮给药'], answer: 1, explain: '静脉注射药物直接进入体循环，生物利用度规定为 100%。' },
          { stem: '栓剂常用的给药部位是：', options: ['胃', '小肠', '直肠', '口腔黏膜'], answer: 2, explain: '栓剂塞入直肠，经直肠黏膜吸收，可部分避开肝首过效应。' }
        ],
        doc: { lead: '剂型决定给药途径、吸收速度和患者依从性，是药学与临床的接口。', sections: [
          { id: 'k1', title: '常见剂型', html: `<p>药物剂型按形态可分为片剂、胶囊剂、颗粒剂、注射剂、软膏剂、栓剂和气雾剂，按给药途径可分为口服、注射、黏膜、皮肤和吸入制剂。剂型决定药物的释放与吸收。</p><p>缓释制剂能减慢药物释放、减少给药次数，使血药浓度平稳；控释制剂近似恒速释药，渗透泵片是典型代表。选择剂型需综合考虑药物性质、治疗需求和患者依从性。</p>` },
          { id: 'k2', title: '吸收与首过效应', html: `<p>口服药物经胃肠道吸收后先进入肝门静脉，部分在肝内被代谢灭活，使进入体循环的药量减少，称为首过效应。首过效应明显的药物可改用舌下、直肠或注射给药。</p><p>生物利用度反映药物进入体循环的程度和速度，静脉注射规定为 100%。剂型辅料、粒径、晶型和制备工艺都会影响溶出与吸收，进而改变生物利用度。</p><ul><li>舌下和直肠给药可部分避开首过效应。</li><li>缓控释制剂可减少血药浓度波动。</li></ul>` }
        ], refs: [] } },
      { title: '药物分析概述', brief: '药典标准、鉴别检查与含量测定。',
        q: [
          { stem: '我国药品质量控制的法定标准是：', options: ['企业内控标准', '中国药典', '产品说明书', '临床试验方案'], answer: 1, explain: '中国药典是国家药品标准，具有法律约束力，是药品检验的法定依据。' },
          { stem: '现行药典中多数化学药含量测定的首选方法是：', options: ['滴定法', '紫外分光光度法', '高效液相色谱法', '薄层色谱法'], answer: 2, explain: 'HPLC 分离能力强、专属性好，是含量测定的主流方法。' },
          { stem: '药品中有关物质的检查通常属于：', options: ['性状检查', '鉴别试验', '含量测定', '限量检查'], answer: 3, explain: '有关物质检查用于控制杂质限度，属于限量检查而非含量测定。' }
        ],
        doc: { lead: '药物分析通过性状、鉴别、检查和含量测定，判断药品是否符合质量标准。', sections: [
          { id: 'k1', title: '质量标准', html: `<p>我国药品质量控制的法定标准是《中国药典》，其内容包括凡例、通则、正文和附录，正文项下设有性状、鉴别、检查、含量测定和贮藏等项目，具有法律约束力。</p><p>药品质量特性为安全、有效和质量可控，三者相互支撑。企业内控标准可高于药典，但不得低于药典；药品注册标准也是药品质量控制的依据。药典每次改版都应关注新增与修订项目。</p>` },
          { id: 'k2', title: '分析方法', html: `<p>鉴别试验利用官能团反应、光谱或色谱特征确认真伪；检查项目控制杂质、水分、重金属、微生物等限度；含量测定用于确定有效成分的量，HPLC 是目前的主流方法。</p><p>分析方法需经过方法学验证，常用指标包括专属性、准确度、精密度、线性、范围、检测限和定量限。药典方法优先使用，非药典方法需验证后方可用于检验。</p><ul><li>鉴别看真伪，检查看纯度，含量测定看多少。</li><li>方法验证是数据可靠的前提。</li></ul>` }
        ], refs: [] } },
      { title: '临床药学与药学服务', brief: 'TDM、ADR 监测与处方审核。',
        q: [
          { stem: '下列最适合开展治疗药物监测的药物是：', options: ['阿莫西林', '对乙酰氨基酚', '地高辛', '维生素 C'], answer: 2, explain: '地高辛治疗窗窄、个体差异大，中毒表现与原发病易混淆，需要监测血药浓度。' },
          { stem: '发现严重药品不良反应后，正确的做法是：', options: ['自行观察不报告', '只在科室内部讨论', '立即删除病历', '按规定及时上报并处理患者'], answer: 3, explain: '严重不良反应应立即救治患者，并按规定通过药品不良反应监测系统上报。' },
          { stem: '处方审核的第一步是：', options: ['合法性审核', '经济性审核', '包装审核', '广告审核'], answer: 0, explain: '处方审核按合法性、规范性、适宜性依次进行，首先确认处方来源和医师资质合法。' }
        ],
        doc: { lead: '临床药学把药学知识用于个体患者，核心是安全、有效、经济和适当用药。', sections: [
          { id: 'k1', title: '治疗药物监测与药学监护', html: `<p>治疗药物监测适用于治疗窗窄、个体差异大或毒性反应难以识别的药物，如地高辛、万古霉素和环孢素。通过测定血药浓度，结合药动学原理调整剂量，可提高疗效并减少中毒。</p><p>药学监护包括采集用药史、评估治疗方案、监测疗效与不良反应以及开展患者教育。药师应与医师、护士协作，形成以患者为中心的药物治疗管理闭环。</p>` },
          { id: 'k2', title: '处方审核与 ADR', html: `<p>处方审核按合法性、规范性和适宜性依次进行，重点核对诊断、药品、剂量、用法、相互作用和配伍禁忌。发现问题应及时与处方医师沟通，不得擅自更改处方。</p><p>药品不良反应分为 A 型和 B 型，A 型与剂量相关、可预测，B 型与剂量无关、多属特异质反应。发现严重不良反应应立即救治患者，并按规定通过监测系统上报。</p><ul><li>处方审核关注合法性、规范性和适宜性。</li><li>用药教育应讲清剂量、时间、疗程和主要不良反应。</li></ul>` }
        ], refs: [] } },
      { title: '药学职业与伦理', brief: '药师职责、患者隐私与专业边界。',
        q: [
          { stem: '药学服务的核心理念是：', options: ['以药品为中心', '以利润为中心', '以医生为中心', '以患者为中心'], answer: 3, explain: '药学服务以患者为中心，目标是改善药物治疗结果和生活质量。' },
          { stem: '药师在处理患者用药信息时，首先应遵守：', options: ['保护患者隐私', '公开患者信息', '随意转发处方', '用于商业推广'], answer: 0, explain: '患者用药信息属于敏感个人信息，药师应严格保密并仅用于诊疗目的。' },
          { stem: '面对缺乏证据的保健品宣传，药师应：', options: ['顺应当事人推荐', '基于证据客观解释并拒绝夸大宣传', '隐瞒风险', '鼓励替代处方药'], answer: 1, explain: '药师应基于科学证据提供客观信息，不得夸大疗效或误导患者替代正规治疗。' }
        ],
        doc: { lead: '药学职业既要求专业能力，也要求守住伦理和法律的边界。', sections: [
          { id: 'k1', title: '药师职责', html: `<p>药师承担药品调配、处方审核、用药指导和药学监护等职责，应在专业范围内对患者用药安全负责。发生用药错误时，应首先保障患者安全，及时处理、报告并记录。</p><p>药师还应参与药品质量管理、药物警戒和合理用药宣传，持续更新药典、法规和循证证据。专业能力与责任意识共同构成药师职业的基础。</p>` },
          { id: 'k2', title: '伦理与沟通', html: `<p>药学伦理强调尊重患者自主、保护隐私、知情同意和公平可及。推荐药物应以适应证和证据为基础，避免商业利益影响专业判断，不得夸大疗效或误导患者。</p><p>沟通时使用患者能理解的语言，确认其真正掌握用法用量和注意事项。面对保健品宣传，应基于证据客观解释，引导患者坚持正规治疗。</p><ul><li>患者隐私和知情同意是基本伦理要求。</li><li>推荐药物应避免利益冲突。</li></ul>` }
        ], refs: [] } }
    ],

    '生物化学': [
      { title: '氨基酸与核苷酸代谢', brief: '脱氨、尿素循环与嘌呤分解。',
        q: [
          { stem: '体内氨解毒的主要途径是：', options: ['尿素循环', '直接排出', '合成谷氨酸', '转氨基'], answer: 0, explain: '氨在肝内经尿素循环合成尿素，经肾排出，是体内氨的主要解毒方式。' },
          { stem: '痛风患者血尿酸升高与哪种代谢异常有关：', options: ['嘧啶代谢', '嘌呤代谢', '脂肪酸代谢', '糖原分解'], answer: 1, explain: '嘌呤分解终产物为尿酸，生成过多或排泄减少可致高尿酸血症和痛风。' },
          { stem: '转氨酶的辅酶是：', options: ['磷酸吡哆醛', 'NAD+', 'FAD', '生物素'], answer: 0, explain: '转氨酶以磷酸吡哆醛即维生素 B6 的活性形式为辅酶，催化氨基在氨基酸与 α-酮酸间转移。' }
        ],
        doc: { lead: '氨基酸代谢围绕氨基的转移与去除展开，核苷酸代谢则连接遗传信息与分解产物。', sections: [
          { id: 'k1', title: '氨基酸代谢', html: `<p>氨基酸代谢的中心是脱氨基，包括转氨基、氧化脱氨基和联合脱氨基。转氨酶以磷酸吡哆醛为辅酶，联合脱氨基是体内主要的脱氨方式，脱下的氨需及时转运和解毒。</p><p>氨在肝内经尿素循环合成尿素，是主要解毒途径；肌肉中氨经丙氨酸-葡萄糖循环运至肝，脑和肌肉中氨可与谷氨酸结合生成谷氨酰胺运输。肝功能严重受损时血氨升高，可诱发肝性脑病。</p><ul><li>转氨基反应把氨基转移给 α-酮酸，生成新的氨基酸。</li><li>尿素循环任一酶缺陷均可导致高氨血症。</li></ul>` },
          { id: 'k2', title: '核苷酸代谢', html: `<p>嘌呤核苷酸以氨基酸、二氧化碳和磷酸核糖为原料合成，嘧啶核苷酸原料包括氨甲酰磷酸和天冬氨酸。嘌呤分解终产物为尿酸，生成过多或排泄减少可致高尿酸血症和痛风。</p><p>抗代谢物可干扰核苷酸合成，如甲氨蝶呤抑制二氢叶酸还原酶，5-氟尿嘧啶抑制胸苷酸合成酶，常用于抗肿瘤治疗。别嘌醇抑制黄嘌呤氧化酶，可降低血尿酸。</p><ul><li>嘌呤分解终产物是尿酸，嘧啶分解产物易溶于水。</li><li>抗代谢药通过与正常代谢物竞争发挥作用。</li></ul>` }
        ], refs: [] } },
      { title: '基因表达与分子生物学技术', brief: '中心法则、PCR 与基因编辑。',
        q: [
          { stem: 'DNA 复制中新链的合成方向是：', options: ['3′→5′', '5′→3′', '两条链均连续', '从两端向中间'], answer: 1, explain: 'DNA 聚合酶只能沿 5′→3′ 方向合成新链，因此有前导链与随从链之分。' },
          { stem: '逆转录过程是指：', options: ['以 DNA 为模板合成 RNA', '以 RNA 为模板合成 DNA', '以蛋白质为模板合成 RNA', '以 RNA 为模板合成蛋白质'], answer: 1, explain: '逆转录酶以 RNA 为模板合成 cDNA，是 RT-PCR 和 cDNA 克隆的基础。' },
          { stem: 'PCR 反应的三个基本步骤是：', options: ['复制、转录、翻译', '解旋、连接、剪切', '变性、退火、延伸', '变性、连接、延伸'], answer: 2, explain: 'PCR 每个循环依次进行高温变性、引物退火和 DNA 聚合酶延伸。' }
        ],
        doc: { lead: '中心法则描述遗传信息的传递方向，分子生物学技术则把这种传递变成可操作的工具。', sections: [
          { id: 'k1', title: '中心法则', html: `<p>中心法则描述遗传信息的传递方向：DNA 通过半保留复制传给子代，转录生成 RNA，再翻译为蛋白质。DNA 聚合酶只能沿 5′→3′ 方向合成新链，因此出现前导链与随从链。</p><p>逆转录酶以 RNA 为模板合成 DNA，是逆转录病毒复制的关键，也是 RT-PCR 和 cDNA 合成的基础。某些 RNA 病毒还可进行 RNA 复制，扩展了中心法则的内涵。朊病毒则通过改变蛋白质构象实现信息传递，是中心法则的补充。</p>` },
          { id: 'k2', title: '常用分子生物学技术', html: `<p>PCR 以变性、退火、延伸三步循环扩增 DNA，具有灵敏度高、特异性强的特点，可用于病原检测、基因分型和突变分析。凝胶电泳按分子大小分离核酸，限制性内切酶识别特定序列并切割 DNA。</p><p>分子杂交、DNA 测序和基因编辑等技术进一步拓展了研究手段。CRISPR-Cas9 通过向导 RNA 定位并切割靶序列，可实现基因敲除和修复，但应用需考虑脱靶与伦理问题。</p><ul><li>PCR 产物需经电泳或测序确认特异性。</li><li>基因编辑的临床转化需严格评估安全性和伦理。</li></ul>` }
        ], refs: [] } },
      { title: '维生素与辅酶', brief: '水溶性维生素、脂溶性维生素与缺乏症。',
        q: [
          { stem: '下列维生素缺乏可引起夜盲症的是：', options: ['维生素 A', '维生素 B1', '维生素 C', '维生素 D'], answer: 0, explain: '维生素 A 参与视紫红质合成，缺乏时暗适应能力下降，导致夜盲症。' },
          { stem: 'NAD+ 分子中含有的维生素是：', options: ['核黄素', '尼克酰胺', '硫胺素', '叶酸'], answer: 1, explain: 'NAD+ 由尼克酰胺（维生素 PP）参与构成，是脱氢酶的辅酶。' },
          { stem: '维生素 C 缺乏的典型表现是：', options: ['坏血病', '佝偻病', '脚气病', '夜盲症'], answer: 0, explain: '维生素 C 参与胶原蛋白羟化，缺乏时毛细血管脆性增加，引起坏血病。' }
        ],
        doc: { lead: '维生素大多不能由人体合成，需从食物摄取，并多以辅酶形式参与代谢。', sections: [
          { id: 'k1', title: '水溶性维生素', html: `<p>B 族维生素多作为辅酶参与代谢：维生素 B1 形成 TPP，参与脱羧和转酮反应；B2 构成 FMN 和 FAD；维生素 PP 构成 NAD+ 和 NADP+；B6 形成磷酸吡哆醛，参与转氨和脱羧。</p><p>叶酸参与一碳单位转移，维生素 B12 参与甲基转移和髓鞘合成，生物素是羧化酶的辅酶。维生素 C 具有还原性，参与胶原蛋白羟化，缺乏时引起坏血病，表现为牙龈出血和伤口难愈。</p>` },
          { id: 'k2', title: '脂溶性维生素', html: `<p>脂溶性维生素包括 A、D、E、K。维生素 A 参与视紫红质合成，缺乏致夜盲症；维生素 D 促进钙磷吸收，缺乏致佝偻病；维生素 E 是抗氧化剂；维生素 K 参与凝血因子合成。</p><p>脂溶性维生素可在体内蓄积，过量摄入可致中毒，如维生素 A 过量引起颅内压升高和肝损害，维生素 D 过量引起高钙血症。补充时应遵循需要量，避免盲目大剂量使用。</p><ul><li>水溶性维生素过量多随尿排出，毒性相对较小。</li><li>脂溶性维生素应避免长期超量补充。</li></ul>` }
        ], refs: [] } },
      { title: '生物氧化与能量代谢', brief: '呼吸链、氧化磷酸化与 ATP 生成。',
        q: [
          { stem: '氧化磷酸化发生的部位是：', options: ['线粒体内膜', '胞质', '内质网', '细胞核'], answer: 0, explain: '呼吸链和 ATP 合酶位于线粒体内膜，氧化磷酸化在此进行。' },
          { stem: '呼吸链中电子传递的最终受体是：', options: ['NAD+', 'FAD', '氧', '细胞色素 c'], answer: 2, explain: '电子经呼吸链传递最终交给氧，氧被还原为水。' },
          { stem: '1 分子 NADH 经氧化磷酸化约生成 ATP 的分子数为：', options: ['1.5', '2.5', '3.5', '5'], answer: 1, explain: '按现行化学渗透计算，NADH 约生成 2.5 分子 ATP，FADH2 约生成 1.5 分子。' }
        ],
        doc: { lead: '生物氧化把营养物中的还原当量交给呼吸链，通过氧化磷酸化转化为 ATP。', sections: [
          { id: 'k1', title: '呼吸链与氧化磷酸化', html: `<p>生物氧化在线粒体内进行，代谢物脱下的氢经呼吸链传递给氧生成水，同时释放能量驱动 ATP 合成。呼吸链由复合体Ⅰ至Ⅳ组成，电子按氧化还原电位由低到高依次传递。</p><p>氧化磷酸化在线粒体内膜进行，电子传递建立质子梯度，质子经 ATP 合酶回流驱动 ADP 磷酸化生成 ATP。NADH 氧化约生成 2.5 分子 ATP，FADH2 约生成 1.5 分子 ATP。</p><ul><li>电子传递与 ATP 合成通过质子梯度偶联。</li><li>ATP 合酶位于线粒体内膜，质子回流驱动其旋转催化。</li></ul>` },
          { id: 'k2', title: '能量代谢与抑制剂', html: `<p>ATP 可由底物水平磷酸化和氧化磷酸化两种方式生成，后者是主要来源。呼吸链抑制剂如鱼藤酮、抗霉素 A 和氰化物可阻断电子传递，导致细胞缺氧样死亡。</p><p>解偶联剂如 2,4-二硝基苯酚使质子梯度消失，电子传递仍进行但不生成 ATP，能量以热的形式释放。理解这些抑制剂有助于分析药物毒性和代谢性疾病机制。</p><ul><li>氰化物抑制细胞色素 c 氧化酶，阻断电子传给氧。</li><li>解偶联剂增加产热，曾用于减肥但因毒性被禁用。</li></ul>` }
        ], refs: [] } }
    ],

    '药物化学': [
      { title: '抗菌药物与抗生素', brief: 'β-内酰胺、磺胺与喹诺酮的结构与机制。',
        q: [
          { stem: '青霉素的母核是：', options: ['7-氨基头孢烷酸', '6-氨基青霉烷酸', '青霉酸', '噻唑烷二酮'], answer: 1, explain: '青霉素母核为 6-氨基青霉烷酸，由 β-内酰胺环与噻唑烷环并合而成。' },
          { stem: '磺胺类抗菌的主要机制是竞争性抑制：', options: ['二氢叶酸还原酶', '二氢蝶酸合成酶', 'DNA 聚合酶', '转肽酶'], answer: 1, explain: '磺胺与对氨基苯甲酸结构相似，竞争细菌二氢蝶酸合成酶，阻碍叶酸合成。' },
          { stem: '氟喹诺酮类的主要作用靶点是：', options: ['DNA 回旋酶', '转肽酶', '二氢蝶酸合成酶', '核糖体 50S 亚基'], answer: 0, explain: '氟喹诺酮抑制细菌 DNA 回旋酶和拓扑异构酶Ⅳ，阻碍 DNA 复制。' }
        ],
        doc: { lead: '抗菌药物按作用靶点分为抑制细胞壁、叶酸、核酸和蛋白质合成的类别，结构母核决定其活性特点。', sections: [
          { id: 'k1', title: 'β-内酰胺类', html: `<p>β-内酰胺类抗生素包括青霉素类和头孢菌素类，前者母核为 6-氨基青霉烷酸，后者为 7-氨基头孢烷酸。二者通过酰化转肽酶抑制细菌细胞壁肽聚糖交联，产生杀菌作用。</p><p>青霉素不耐酸、不耐酶且抗菌谱窄，结构改造得到耐酸、耐酶和广谱品种。细菌产生 β-内酰胺酶水解 β-内酰胺环是主要耐药机制，联合克拉维酸等酶抑制剂可恢复敏感性。</p><ul><li>β-内酰胺环张力大，易被酸、碱和酶破坏。</li><li>侧链改造可改善抗菌谱和药动学性质。</li></ul>` },
          { id: 'k2', title: '其他抗菌药', html: `<p>磺胺类与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合成酶，阻碍细菌叶酸合成，常与甲氧苄啶联用。喹诺酮类抑制 DNA 回旋酶和拓扑异构酶Ⅳ，阻碍细菌 DNA 复制。</p><p>大环内酯类结合细菌核糖体 50S 亚基抑制蛋白质合成，氨基糖苷类结合 30S 亚基并引起读码错误。抗结核药中异烟肼抑制分枝菌酸合成，利福平抑制依赖 DNA 的 RNA 聚合酶。</p><ul><li>磺胺与甲氧苄啶联用可双重阻断叶酸合成。</li><li>抗结核治疗需联合用药以延缓耐药。</li></ul>` }
        ], refs: [] } },
      { title: '心血管系统药物', brief: '他汀、硝酸酯、ACEI 与强心药。',
        q: [
          { stem: '他汀类调脂药的作用靶点是：', options: ['HMG-CoA 还原酶', '乙酰CoA 羧化酶', '角鲨烯环氧化酶', '胆固醇酯转移酶'], answer: 0, explain: '他汀类抑制 HMG-CoA 还原酶，减少肝内胆固醇合成，上调 LDL 受体。' },
          { stem: '硝酸甘油缓解心绞痛的主要机制是：', options: ['阻断钙通道', '释放 NO 激活鸟苷酸环化酶', '抑制 β 受体', '抑制磷酸二酯酶'], answer: 1, explain: '硝酸甘油释放 NO，使 cGMP 升高、血管平滑肌舒张，降低心脏前后负荷。' },
          { stem: '卡托普利属于：', options: ['血管紧张素Ⅱ受体拮抗剂', 'β 受体阻断药', '血管紧张素转化酶抑制剂', '钙通道阻滞药'], answer: 2, explain: '卡托普利抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成，属 ACEI。' }
        ],
        doc: { lead: '心血管药物通过调节血脂、血管张力、心肌收缩和节律发挥作用，结构细节影响选择性和不良反应。', sections: [
          { id: 'k1', title: '调脂与抗心绞痛', html: `<p>他汀类抑制 HMG-CoA 还原酶，减少肝内胆固醇合成，上调 LDL 受体而降低血胆固醇，是调脂治疗的基石。贝特类激活过氧化物酶体增殖物激活受体 α，主要降低甘油三酯。</p><p>硝酸酯类释放一氧化氮，激活鸟苷酸环化酶使 cGMP 升高，血管平滑肌舒张，降低心脏前后负荷，缓解心绞痛。β 受体阻断药减慢心率、降低心肌耗氧，钙通道阻滞药扩张血管并减少心肌收缩。</p><ul><li>他汀类需关注肝酶升高和肌病。</li><li>硝酸酯类连续使用可产生耐受性，需设无硝酸酯间期。</li></ul>` },
          { id: 'k2', title: '抗高血压与心衰', html: `<p>抗高血压药包括利尿药、ACEI、ARB、钙通道阻滞药和 β 受体阻断药等。ACEI 抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成并抑制缓激肽降解，干咳是其特征性不良反应。</p><p>强心苷抑制 Na+-K+-ATP 酶，增加心肌细胞内钙，增强心肌收缩力并减慢心率，用于心力衰竭伴房颤。沙库巴曲缬沙坦同时抑制脑啡肽酶和血管紧张素受体，可改善心衰预后。</p><ul><li>ACEI 与 ARB 不宜联合使用。</li><li>强心苷治疗窗窄，低血钾易诱发中毒。</li></ul>` }
        ], refs: [] } },
      { title: '神经系统药物', brief: '阿片类、局麻药与精神神经药。',
        q: [
          { stem: '吗啡镇痛主要激动：', options: ['μ 阿片受体', 'κ 阿片受体', 'δ 阿片受体', 'N 胆碱受体'], answer: 0, explain: '吗啡激动 μ 阿片受体产生镇痛、欣快与呼吸抑制。' },
          { stem: '阿托品的作用机制是：', options: ['激动 M 胆碱受体', '阻断 M 胆碱受体', '阻断 N 胆碱受体', '激动 α 受体'], answer: 1, explain: '阿托品竞争性阻断 M 受体，表现为心率加快、腺体分泌减少与瞳孔扩大。' },
          { stem: '苯二氮䓬类药物的作用靶点是：', options: ['GABA-A 受体', '阿片受体', '多巴胺 D2 受体', '5-HT 受体'], answer: 0, explain: '苯二氮䓬类作用于 GABA-A 受体，增强氯离子内流产生中枢抑制。' }
        ],
        doc: { lead: '神经系统药物作用于受体、离子通道和神经递质系统，结构决定其靶点与作用强度。', sections: [
          { id: 'k1', title: '镇痛与麻醉', html: `<p>阿片类镇痛药激动 μ、κ、δ 阿片受体，吗啡激动 μ 受体产生镇痛、欣快和呼吸抑制，反复使用可致耐受与依赖。纳洛酮是阿片受体拮抗剂，用于阿片类中毒解救。</p><p>局部麻醉药阻断电压门控钠通道，使神经冲动不能传导。普鲁卡因含酯键易水解，利多卡因含酰胺键较稳定，作用更强、持续时间更长，是临床常用局麻药。</p><ul><li>阿片类中毒表现为呼吸抑制和瞳孔缩小。</li><li>局麻药误入血管可引起中枢和心脏毒性。</li></ul>` },
          { id: 'k2', title: '精神与神经药', html: `<p>苯二氮䓬类作用于 GABA-A 受体，增强氯离子内流，产生抗焦虑、镇静催眠和抗惊厥作用，地西泮为其代表。长期使用可致耐受和依赖，停药应逐渐减量。</p><p>抗抑郁药包括选择性 5-羟色胺再摄取抑制剂和三环类，后者易致心律失常和抗胆碱作用。抗精神病药主要阻断多巴胺 D2 受体，长期使用可致锥体外系反应和高催乳素血症。</p><ul><li>苯二氮䓬类过量可用氟马西尼拮抗。</li><li>抗精神病药需关注代谢综合征和QT间期延长。</li></ul>` }
        ], refs: [] } },
      { title: '抗肿瘤与抗病毒药物', brief: '烷化剂、抗代谢、靶向药与抗病毒药。',
        q: [
          { stem: '甲氨蝶呤抗肿瘤的主要机制是抑制：', options: ['二氢叶酸还原酶', '拓扑异构酶Ⅰ', '微管聚合', 'DNA 回旋酶'], answer: 0, explain: '甲氨蝶呤与叶酸结构相似，抑制二氢叶酸还原酶，阻断胸腺嘧啶合成。' },
          { stem: '顺铂抗肿瘤的作用靶点是：', options: ['微管蛋白', 'DNA', '核糖体', '叶酸合成酶'], answer: 1, explain: '顺铂与 DNA 鸟嘌呤结合形成链内交联，抑制 DNA 复制和转录。' },
          { stem: '阿昔洛韦抗疱疹病毒的机制是抑制：', options: ['病毒 DNA 聚合酶', '病毒蛋白酶', '宿主 RNA 聚合酶', '病毒神经氨酸酶'], answer: 0, explain: '阿昔洛韦经病毒胸苷激酶活化后，抑制病毒 DNA 聚合酶，选择性较高。' }
        ],
        doc: { lead: '抗肿瘤药通过损伤 DNA 或干扰核酸合成抑制增殖，抗病毒药则针对病毒特有的酶和复制环节。', sections: [
          { id: 'k1', title: '抗肿瘤药', html: `<p>抗肿瘤药按机制分为烷化剂、抗代谢药、抗肿瘤抗生素、植物生物碱和铂类。烷化剂如环磷酰胺与 DNA 发生共价结合，抗代谢药如甲氨蝶呤干扰叶酸代谢，顺铂与 DNA 交联抑制复制。</p><p>传统细胞毒药物选择性差，常见骨髓抑制、恶心呕吐和脱发。靶向药物针对特定分子靶点，如酪氨酸激酶抑制剂伊马替尼抑制 BCR-ABL 融合蛋白，单克隆抗体可阻断信号通路或介导免疫杀伤。</p><ul><li>烷化剂属细胞周期非特异性药物。</li><li>抗代谢药多作用于 S 期，属周期特异性药物。</li></ul>` },
          { id: 'k2', title: '抗病毒与抗真菌药', html: `<p>阿昔洛韦是核苷类抗病毒药，在病毒胸苷激酶作用下活化，抑制病毒 DNA 聚合酶，对疱疹病毒选择性高。逆转录酶抑制剂和蛋白酶抑制剂是抗艾滋病联合治疗的核心。</p><p>唑类抗真菌药抑制真菌麦角固醇合成，两性霉素 B 与麦角固醇结合形成孔道。抗病毒和抗真菌药物需关注肝肾功能、药物相互作用及耐药问题。</p><ul><li>阿昔洛韦需经病毒激酶活化，故对宿主细胞毒性较低。</li><li>两性霉素 B 肾毒性明显，需监测肾功能和电解质。</li></ul>` }
        ], refs: [] } }
    ],

    '药理学': [
      { title: '心血管系统药理', brief: '抗高血压、抗心绞痛与抗心律失常。',
        q: [
          { stem: '地高辛中毒最常见的心律失常是：', options: ['心房颤动', '室性早搏', '窦性心动过速', '心房扑动'], answer: 1, explain: '地高辛中毒常见室性早搏，可呈二联律，低血钾可加重中毒。' },
          { stem: '普萘洛尔的主要禁忌证是：', options: ['高血压', '心绞痛', '支气管哮喘', '甲状腺功能亢进'], answer: 2, explain: '普萘洛尔阻断 β2 受体，可诱发支气管痉挛，哮喘患者禁用。' },
          { stem: '呋塞米的主要作用部位是：', options: ['近曲小管', '远曲小管', '集合管', '髓袢升支粗段'], answer: 3, explain: '呋塞米抑制髓袢升支粗段的 Na+-K+-2Cl- 同向转运体，产生强大利尿作用。' }
        ],
        doc: { lead: '心血管药理围绕血压、心肌耗氧、收缩力和节律四个环节展开。', sections: [
          { id: 'k1', title: '抗高血压与抗心绞痛', html: `<p>抗高血压药按机制分为利尿药、ACEI、ARB、钙通道阻滞药、β 受体阻断药等。ACEI 和 ARB 减少血管紧张素Ⅱ作用，适用于合并糖尿病或蛋白尿的患者，但妊娠期禁用。</p><p>心绞痛治疗以降低心肌耗氧和改善冠脉供血为目标。硝酸酯类扩张静脉降低前负荷，β 受体阻断药减慢心率，钙通道阻滞药扩张冠脉，三者常联合使用。</p><ul><li>ACEI 常见干咳，ARB 干咳少见。</li><li>β 受体阻断药突然停药可致反跳。</li></ul>` },
          { id: 'k2', title: '心衰与抗心律失常', html: `<p>心力衰竭治疗以利尿药减轻容量负荷，ACEI 或 ARB、β 受体阻断药和醛固酮受体拮抗剂改善预后，强心苷用于症状控制。用药需从小剂量开始，逐渐调整至目标剂量。</p><p>抗心律失常药按 Vaugham-Williams 分类为Ⅰ至Ⅳ类，分别阻滞钠通道、β 受体、钾通道和钙通道。多数抗心律失常药本身可致心律失常，使用时需监测心电图和电解质。</p><ul><li>地高辛治疗窗窄，需监测血药浓度和血钾。</li><li>胺碘酮可致甲状腺功能和肺纤维化异常。</li></ul>` }
        ], refs: [] } },
      { title: '内分泌系统药理', brief: '降糖药、甲状腺药与糖皮质激素。',
        q: [
          { stem: '胰岛素的主要不良反应是：', options: ['低血糖', '高血糖', '低血钾', '过敏反应'], answer: 0, explain: '胰岛素过量或进食不足可引起低血糖，表现为出汗、心悸和意识障碍。' },
          { stem: '二甲双胍的主要作用机制是：', options: ['促进胰岛素分泌', '减少肝糖输出并改善胰岛素抵抗', '延缓碳水化合物吸收', '直接抑制葡萄糖重吸收'], answer: 1, explain: '二甲双胍减少肝糖输出、改善外周胰岛素敏感性，低血糖风险小。' },
          { stem: '糖皮质激素长期大剂量使用的不良反应不包括：', options: ['库欣综合征', '骨质疏松', '血糖升高', '低血糖'], answer: 3, explain: '糖皮质激素升高血糖而非降低血糖，长期使用可致类固醇性糖尿病。' }
        ],
        doc: { lead: '内分泌药物通过补充或拮抗激素发挥作用，剂量调整需结合血糖、激素水平和临床症状。', sections: [
          { id: 'k1', title: '降糖药', html: `<p>胰岛素是治疗 1 型糖尿病的必需药物，主要不良反应为低血糖。口服降糖药中二甲双胍减少肝糖输出、改善胰岛素抵抗，是 2 型糖尿病的一线用药。</p><p>磺脲类促胰岛素分泌，格列奈类起效快，α-葡萄糖苷酶抑制剂延缓碳水化合物吸收，噻唑烷二酮类增加胰岛素敏感性。选药需考虑体重、肝肾功能和低血糖风险。</p><ul><li>胰岛素按起效速度分为速效、短效、中效和长效。</li><li>二甲双胍在肾功能不全者可能诱发乳酸酸中毒。</li></ul>` },
          { id: 'k2', title: '甲状腺与糖皮质激素', html: `<p>甲状腺功能亢进常用硫脲类药物，丙硫氧嘧啶抑制甲状腺激素合成并抑制外周 T4 转化为 T3，甲巯咪唑作用更强。碘剂大剂量可抑制甲状腺激素释放，用于术前准备和甲亢危象。</p><p>糖皮质激素具有抗炎、抗免疫和抗休克作用，长期大剂量使用可致库欣综合征、骨质疏松、血糖升高和感染扩散。停药需逐渐减量，以免诱发肾上腺皮质功能不全。</p><ul><li>丙硫氧嘧啶可致肝损害，需监测肝功能。</li><li>长期激素治疗应采用最小有效剂量并逐步减停。</li></ul>` }
        ], refs: [] } },
      { title: '抗微生物药物药理', brief: '抗菌机制、耐药与合理用药。',
        q: [
          { stem: '青霉素的抗菌机制是：', options: ['抑制细胞壁合成', '抑制蛋白质合成', '抑制核酸合成', '抑制叶酸代谢'], answer: 0, explain: '青霉素抑制转肽酶，阻碍细胞壁肽聚糖交联，对繁殖期细菌有杀菌作用。' },
          { stem: '氨基糖苷类的主要不良反应是：', options: ['肝毒性和骨髓抑制', '耳毒性和肾毒性', '胃肠道反应', '光敏反应'], answer: 1, explain: '氨基糖苷类可损伤第八对脑神经和肾小管，用药期间应监测听力和肾功能。' },
          { stem: '喹诺酮类禁用于儿童和孕妇的主要原因是：', options: ['影响软骨发育', '引起耳聋', '抑制骨髓', '导致牙齿黄染'], answer: 0, explain: '喹诺酮类可影响幼年动物软骨发育，故儿童和孕妇禁用。' }
        ],
        doc: { lead: '抗菌药物按靶点分为四类，合理用药和耐药防控是药理学的核心议题。', sections: [
          { id: 'k1', title: '抗菌机制与耐药', html: `<p>抗菌药物按机制分为抑制细胞壁合成、抑制蛋白质合成、抑制核酸合成和抑制叶酸代谢四类。青霉素和头孢菌素抑制细胞壁，氨基糖苷类和大环内酯类抑制蛋白质合成。</p><p>细菌耐药机制包括产生灭活酶、改变靶点、减少药物摄取和增加外排。合理使用抗菌药物、按病原学结果选药、足量足疗程可延缓耐药产生。</p><ul><li>β-内酰胺类属时间依赖性杀菌药。</li><li>氨基糖苷类属浓度依赖性杀菌药。</li></ul>` },
          { id: 'k2', title: '合理应用', html: `<p>抗菌药物应用应明确适应证，经验治疗前尽量留取标本做病原学检查。联合用药适用于混合感染、重症感染和需延缓耐药的结核治疗，但不宜盲目联合。</p><p>特殊人群用药需调整剂量，如肾功能不全者减少氨基糖苷类剂量，孕妇禁用喹诺酮类和四环素类。用药期间应监测疗效和不良反应，及时调整方案。</p><ul><li>病毒性感冒不应常规使用抗菌药物。</li><li>抗菌药物分级管理分为非限制、限制和特殊使用三级。</li></ul>` }
        ], refs: [] } },
      { title: '抗肿瘤与免疫药理', brief: '细胞毒药、靶向药与免疫调节。',
        q: [
          { stem: '环磷酰胺属于：', options: ['烷化剂', '抗代谢药', '抗肿瘤抗生素', '植物生物碱'], answer: 0, explain: '环磷酰胺是氮芥类烷化剂，需经肝细胞色素 P450 活化后发挥作用。' },
          { stem: '甲氨蝶呤属于：', options: ['烷化剂', '抗代谢药', '铂类', '激素类'], answer: 1, explain: '甲氨蝶呤结构与叶酸相似，属抗代谢药，抑制二氢叶酸还原酶。' },
          { stem: '环孢素免疫抑制的主要机制是抑制：', options: ['钙调磷酸酶', '二氢叶酸还原酶', '环氧合酶', '血管紧张素转化酶'], answer: 0, explain: '环孢素与亲环素结合后抑制钙调磷酸酶，减少白细胞介素-2 生成，阻断 T 细胞活化。' }
        ],
        doc: { lead: '抗肿瘤药治疗指数低，免疫调节药则用于移植排斥和自身免疫病。', sections: [
          { id: 'k1', title: '抗肿瘤药', html: `<p>抗肿瘤药分为细胞周期特异性和非特异性药物。烷化剂如环磷酰胺属周期非特异性，抗代谢药如甲氨蝶呤主要作用于 S 期，长春新碱作用于 M 期，合理序贯用药可提高疗效。</p><p>抗肿瘤药常见不良反应包括骨髓抑制、胃肠道反应、脱发和肝肾功能损害。用药期间应定期检查血象和肝肾功能，必要时使用集落刺激因子和止吐药支持治疗。</p><ul><li>蒽环类可致心脏毒性，需限制累积剂量。</li><li>顺铂需充分水化以减轻肾毒性。</li></ul>` },
          { id: 'k2', title: '免疫药理', html: `<p>免疫抑制剂环孢素抑制钙调磷酸酶，减少白细胞介素-2 生成，用于器官移植抗排斥。他克莫司作用相似但更强，二者均需监测血药浓度，警惕肾毒性。</p><p>免疫增强剂和生物制剂如干扰素、白细胞介素和单克隆抗体，可用于肿瘤和自身免疫病治疗。使用生物制剂前应筛查感染和过敏史，并监测免疫相关不良反应。</p><ul><li>环孢素与他克莫司均经 CYP3A4 代谢，相互作用多。</li><li>免疫抑制患者感染风险升高，需加强监测。</li></ul>` }
        ], refs: [] } }
    ],

    '药剂学': [
      { title: '散剂、颗粒剂与胶囊剂', brief: '粉碎混合、制粒与胶囊填充。',
        q: [
          { stem: '胶囊剂的主要优点不包括：', options: ['掩盖药物不良气味', '保护光敏药物', '提高药物稳定性', '使所有药物都适合胶囊填充'], answer: 3, explain: '胶囊剂可掩盖气味、保护光敏药物，但易吸湿或与囊壳作用的药物并不适合制成胶囊。' },
          { stem: '颗粒剂制备最常用的方法是：', options: ['湿法制粒', '干馏法', '熔融拉丝', '冷冻干燥'], answer: 0, explain: '湿法制粒将药物与辅料加润湿剂制成软材，再制粒干燥，是颗粒剂最常用的制备方法。' },
          { stem: '外用散剂的粒度要求通常为：', options: ['最粗粉', '粗粉', '中粉', '最细粉'], answer: 3, explain: '外用散剂直接接触皮肤或黏膜，通常要求为最细粉，以减少机械刺激并利于吸收。' }
        ],
        doc: { lead: '散剂、颗粒剂和胶囊剂都属于口服固体剂型，制备的核心是混合均匀和成型稳定。', sections: [
          { id: 'k1', title: '散剂与颗粒剂', html: `<p>散剂是药物与辅料混合制成的粉末状制剂，分为内服和外用散剂，具有制备简单、分散快的特点。颗粒剂由药物与辅料制成颗粒，流动性好、便于分剂量，常用湿法制粒。</p><p>散剂需检查均匀度、水分和装量差异，外用散剂还应检查粒度，通常要求为最细粉。颗粒剂需检查粒度、水分、溶化性和装量差异，泡腾颗粒遇水应迅速崩解。</p><ul><li>混合时应遵循等量递加原则，防止组分分层。</li><li>易吸湿药物制粒时需控制环境湿度。</li></ul>` },
          { id: 'k2', title: '胶囊剂', html: `<p>胶囊剂分为硬胶囊和软胶囊，可掩盖药物不良气味、保护光敏或易氧化药物，并提高稳定性。硬胶囊由明胶或羟丙甲纤维素制成，填充药物粉末或颗粒；软胶囊可填充油状液体或混悬液。</p><p>胶囊剂需检查装量差异、崩解时限和微生物限度，肠溶胶囊应在肠液中崩解。胶囊易吸潮，应密封贮存于阴凉干燥处；明胶胶囊与醛类、还原性药物可能发生交联。</p><ul><li>硬胶囊通常应在 30 分钟内崩解。</li><li>易溶性药物不宜直接制成胶囊，以免囊壳破裂。</li></ul>` }
        ], refs: [] } },
      { title: '软膏剂与栓剂', brief: '基质分类、制备与质量检查。',
        q: [
          { stem: '下列属于软膏剂油脂性基质的是：', options: ['凡士林', '聚乙二醇', '羧甲纤维素钠', '甘油明胶'], answer: 0, explain: '凡士林是烃类油脂性基质，保湿性好但油腻；聚乙二醇属水溶性基质。' },
          { stem: '栓剂最常用的油脂性基质是：', options: ['聚乙二醇', '可可豆脂', '甘油明胶', '卡波姆'], answer: 1, explain: '可可豆脂熔点在体温附近、熔化后易与体液混合，是经典油脂性栓剂基质。' },
          { stem: '下列不属于软膏剂常用基质的是：', options: ['凡士林', '羊毛脂', '聚乙二醇', '可可豆脂'], answer: 3, explain: '可可豆脂是栓剂基质，不是软膏剂常用基质；凡士林、羊毛脂和聚乙二醇均可作软膏基质。' }
        ],
        doc: { lead: '半固体制剂依靠基质把药物送到皮肤或腔道，基质的性质决定释放和吸收。', sections: [
          { id: 'k1', title: '软膏剂', html: `<p>软膏剂由药物与基质组成，常用基质分为油脂性、乳剂型和水溶性三类。油脂性基质如凡士林、羊毛脂，保湿性好但油腻；乳剂型基质易洗除，水溶性基质如聚乙二醇适用于分泌物较多的创面。</p><p>软膏剂应均匀、细腻，无刺激性，需检查粒度、装量、微生物限度和无菌。制备时药物应先粉碎并过筛，与基质逐渐混合，乳剂型软膏需控制乳化温度和时间。</p><ul><li>油脂性基质适用于干燥、皲裂的皮肤。</li><li>水溶性基质易洗除，适合湿润创面。</li></ul>` },
          { id: 'k2', title: '栓剂', html: `<p>栓剂是药物与基质制成的供腔道给药的固体制剂，常用基质为可可豆脂和半合成脂肪酸甘油酯。栓剂塞入直肠后熔化或溶解，药物经直肠黏膜吸收，可部分避开肝首过效应。</p><p>栓剂制备常用热熔法，需计算置换价以保证药物含量准确。栓剂应检查重量差异、融变时限和微生物限度，贮存于阴凉处，避免受热变形。</p><ul><li>置换价是药物重量与同体积基质重量之比。</li><li>栓剂应避免与体温接近的环境长期存放。</li></ul>` }
        ], refs: [] } },
      { title: '气雾剂与粉雾剂', brief: '抛射剂、吸入装置与肺部沉积。',
        q: [
          { stem: '气雾剂的抛射剂主要作用是：', options: ['提供动力并形成雾滴', '增加药物溶解度', '调节 pH', '防腐'], answer: 0, explain: '抛射剂在容器内形成压力，使用时推动药液喷出并使之雾化。' },
          { stem: '吸入粉雾剂的特点是：', options: ['必须使用氟氯烷烃', '不使用抛射剂，依靠患者吸气分散', '只能用于鼻腔', '药物不能进入肺部'], answer: 1, explain: '粉雾剂以微粉形式装填，不使用抛射剂，依靠患者吸气将药粉分散吸入肺内。' },
          { stem: '吸入气雾剂雾滴粒径通常应在：', options: ['1～5 微米', '20～50 微米', '100 微米以上', '0.01 微米以下'], answer: 0, explain: '1～5 微米的雾滴可沉积于肺部，粒径过大易沉积于上呼吸道，过小则随呼气排出。' }
        ],
        doc: { lead: '气雾剂、粉雾剂和喷雾剂通过不同动力把药物分散成微粒，用于局部或全身治疗。', sections: [
          { id: 'k1', title: '气雾剂', html: `<p>气雾剂由耐压容器、抛射剂、药物和阀门系统组成，抛射剂提供动力并形成雾滴。常用抛射剂为氢氟烷烃，可替代破坏臭氧层的氟氯烷烃，按内容物可分为溶液型、混悬型和乳剂型。</p><p>气雾剂需检查每揿主药含量、每瓶总揿次、雾滴粒径分布、泄漏率和压力。吸入气雾剂雾滴粒径多在 1～5 微米，可沉积于肺部，发挥局部或全身作用。</p><ul><li>耐压容器应避免高温、撞击和明火。</li><li>使用前摇匀可使混悬型气雾剂剂量均匀。</li></ul>` },
          { id: 'k2', title: '粉雾剂与喷雾剂', html: `<p>吸入粉雾剂不使用抛射剂，药物以微粉形式装入胶囊或储库，依靠患者吸气将药粉分散吸入肺内。其优点是避免抛射剂、剂量准确，但对吸气流速和装置操作要求较高。</p><p>喷雾剂借助手动泵产生雾滴，用于鼻腔或口腔黏膜给药。使用吸入制剂应进行患者教育，讲清摇匀、呼气、吸气和屏气的配合，确保药物有效沉积。</p><ul><li>粉雾剂需防潮保存，避免微粉聚集。</li><li>吸入后漱口可减少口咽部不良反应。</li></ul>` }
        ], refs: [] } },
      { title: '药物制剂稳定性与配伍变化', brief: '水解氧化、稳定性试验与配伍禁忌。',
        q: [
          { stem: '酯类药物水解的主要影响因素是：', options: ['pH', '颜色', '包装大小', '片重'], answer: 0, explain: '酯类水解受 pH 影响显著，通常存在最稳定的 pH 范围，调节 pH 可延缓水解。' },
          { stem: '药物制剂稳定性试验不包括：', options: ['影响因素试验', '加速试验', '长期试验', '急性毒性试验'], answer: 3, explain: '稳定性试验包括影响因素试验、加速试验和长期试验，急性毒性试验属于安全性评价。' },
          { stem: '下列属于物理配伍变化的是：', options: ['潮解与液化', '变色', '产气', '效价下降'], answer: 0, explain: '潮解、液化、沉淀和分层属于物理配伍变化；变色、产气和效价下降属于化学配伍变化。' }
        ],
        doc: { lead: '制剂稳定性决定有效期和贮存条件，配伍变化则关系到临床联合用药的安全。', sections: [
          { id: 'k1', title: '制剂稳定性', html: `<p>药物制剂稳定性受温度、湿度、光照、pH 和氧气等因素影响。水解和氧化是化学不稳定的主要形式，酯类、酰胺类和苷类药物易水解，酚类、芳胺类药物易氧化。</p><p>提高稳定性的措施包括调节 pH、加入抗氧剂和金属离子络合剂、避光密封、控制水分和采用包衣或包合技术。稳定性试验包括影响因素试验、加速试验和长期试验，用于确定有效期和贮存条件。</p><ul><li>加速试验通常在 40 ℃、相对湿度 75% 条件下进行。</li><li>一级反应半衰期与初浓度无关。</li></ul>` },
          { id: 'k2', title: '配伍变化', html: `<p>配伍变化分为物理、化学和药理配伍变化。物理变化表现为潮解、液化、沉淀或分层，化学变化表现为变色、产气或效价下降，药理变化则指疗效或毒性改变。</p><p>静脉输液配伍应遵循可配伍性原则，注意 pH、溶媒和药物浓度，避免多种药物在同一容器中混合。发现配伍禁忌应立即停止配制，查阅资料并更换输液方案。</p><ul><li>配伍禁忌分为可见和不可见两类。</li><li>输液配制后应观察颜色、澄明度和沉淀。</li></ul>` }
        ], refs: [] } }
    ],

    '药物分析': [
      { title: '紫外-可见分光光度法', brief: '电子跃迁、朗伯-比尔定律与应用。',
        q: [
          { stem: '朗伯-比尔定律的表达式是：', options: ['A=εbc', 'A=bc/ε', 'A=ε/bc', 'A=εb/c'], answer: 0, explain: '吸光度 A 等于摩尔吸光系数 ε、浓度 c 和光程 b 的乘积。' },
          { stem: '紫外-可见分光光度法常用的定量参数是：', options: ['最大吸收波长处的吸光度', '溶液的旋光度', '折光率', '电导率'], answer: 0, explain: '在最大吸收波长处测定吸光度，灵敏度较高且干扰相对较小。' },
          { stem: '为减小偏离比尔定律的误差，吸光度宜控制在：', options: ['0.2～0.8', '1.5～2.0', '2.5～3.0', '任意范围'], answer: 0, explain: '吸光度过高或过低都会增大相对误差，通常控制在 0.2～0.8 之间。' }
        ],
        doc: { lead: '紫外-可见分光光度法基于电子跃迁，是药物鉴别和含量测定的常用方法。', sections: [
          { id: 'k1', title: '原理与仪器', html: `<p>紫外-可见分光光度法基于分子对紫外或可见光的吸收，电子从基态跃迁到激发态。共轭体系越大，最大吸收波长越向长波方向移动，吸收强度与跃迁概率有关。</p><p>朗伯-比尔定律表明吸光度与溶液浓度和光程成正比，即 A=εbc。浓度过高、存在散射或多组分干扰时会偏离线性，测定应在吸光度 0.2～0.8 范围内进行。</p><ul><li>光源常用氘灯和钨灯，分别覆盖紫外和可见区。</li><li>比色皿材质应与测定波长匹配。</li></ul>` },
          { id: 'k2', title: '应用', html: `<p>紫外分光光度法常用于药物鉴别、含量测定和纯度检查。鉴别可比较最大吸收波长和吸光度比值，含量测定可用对照品比较法或吸收系数法，操作简便、成本较低。</p><p>测定时应选择最大吸收波长以获较高灵敏度，并用空白溶剂校正。对于复方制剂，可利用导数光谱或双波长法消除干扰，必要时改用 HPLC 提高专属性。</p><ul><li>吸收系数法需使用药典规定的吸收系数。</li><li>溶剂 pH 会影响解离状态和吸收光谱。</li></ul>` }
        ], refs: [] } },
      { title: '红外光谱与色谱联用技术', brief: '官能团识别、GC-MS 与 LC-MS/MS。',
        q: [
          { stem: '红外光谱主要用于：', options: ['鉴别官能团和分子结构', '测定血药浓度', '分离混合物', '测定分子量'], answer: 0, explain: '红外光谱反映分子振动特征，特征区吸收峰可用于识别官能团和确证结构。' },
          { stem: '羰基 C=O 的强吸收峰通常出现在：', options: ['1700 cm-1 附近', '3300 cm-1 附近', '1000 cm-1 以下', '4000 cm-1 以上'], answer: 0, explain: '羰基伸缩振动吸收强，通常出现在 1700 cm-1 附近，共轭时向低波数移动。' },
          { stem: 'LC-MS/MS 最适合用于：', options: ['复杂基质中微量药物测定', '无机盐含量测定', '水分测定', '熔点测定'], answer: 0, explain: 'LC-MS/MS 分离能力强、灵敏度高、专属性好，适合血药浓度和杂质等复杂基质中微量成分测定。' }
        ],
        doc: { lead: '红外光谱提供结构信息，色谱-质谱联用则把分离、定性和定量结合在一起。', sections: [
          { id: 'k1', title: '红外光谱', html: `<p>红外光谱反映分子振动的能量变化，主要用于鉴别官能团和确定分子结构。红外光谱分为特征区和指纹区，特征区 4000～1300 cm-1 提供官能团信息，指纹区反映分子整体特征。</p><p>常见基团吸收峰：O-H 在 3300 cm-1 附近宽峰，C=O 在 1700 cm-1 附近强峰，N-H 在 3300 cm-1 附近，C-O 在 1000～1300 cm-1。氢键和共轭会使吸收峰向低波数移动。</p><ul><li>指纹区差异可用于比对鉴别。</li><li>样品需干燥，水会干扰红外测定。</li></ul>` },
          { id: 'k2', title: '色谱-质谱联用', html: `<p>色谱-质谱联用将色谱的分离能力与质谱的定性能力结合。GC-MS 适用于挥发性、热稳定性成分，LC-MS/MS 适用于极性大、热不稳定药物，广泛用于血药浓度测定和杂质鉴定。</p><p>联用技术可提供保留时间、分子量和碎片离子信息，提高定性准确度。方法开发需考虑离子源、碰撞能量和基质效应，并用同位素内标校正定量误差。</p><ul><li>多反应监测模式可显著提高灵敏度和选择性。</li><li>基质效应应通过方法学验证评估。</li></ul>` }
        ], refs: [] } },
      { title: '滴定分析法', brief: '酸碱、非水、氧化还原与配位滴定。',
        q: [
          { stem: '非水滴定法常用于测定：', options: ['弱碱性药物', '强酸性药物', '无机盐', '水分'], answer: 0, explain: '弱碱性药物在水溶液中突跃不明显，可在冰醋酸中用高氯酸滴定，提高终点敏锐度。' },
          { stem: '高氯酸滴定液标定常用的基准物质是：', options: ['邻苯二甲酸氢钾', '氯化钠', '碳酸钠', '草酸钠'], answer: 0, explain: '邻苯二甲酸氢钾纯度高、稳定，是标定高氯酸滴定液的常用基准物质。' },
          { stem: '碘量法测定维生素 C 时常用的指示剂是：', options: ['淀粉', '酚酞', '甲基橙', '结晶紫'], answer: 0, explain: '碘量法以淀粉为指示剂，滴定至蓝色消失或出现即为终点。' }
        ],
        doc: { lead: '滴定分析法依据反应类型分为酸碱、氧化还原、配位和沉淀滴定，是药物含量测定的经典方法。', sections: [
          { id: 'k1', title: '酸碱与非水滴定', html: `<p>滴定分析法按反应类型分为酸碱滴定、氧化还原滴定、配位滴定和沉淀滴定。酸碱滴定以指示剂变色判断终点，适用于酸性或碱性较强的药物，弱碱药物常用非水滴定提高突跃。</p><p>非水滴定常用冰醋酸为溶剂，高氯酸为滴定液，结晶紫为指示剂，适用于弱碱性药物的含量测定。高氯酸滴定液需用邻苯二甲酸氢钾标定，并做空白校正。</p><ul><li>非水溶剂可增强弱碱的碱性，使滴定突跃明显。</li><li>滴定操作应避免水分进入，否则影响终点。</li></ul>` },
          { id: 'k2', title: '氧化还原与配位滴定', html: `<p>氧化还原滴定包括碘量法、亚硝酸钠法和高锰酸钾法。碘量法可直接或间接测定维生素 C、葡萄糖等还原性或氧化性物质，淀粉为指示剂，终点为蓝色消失或出现。</p><p>配位滴定以 EDTA 为滴定液，通过金属指示剂判断终点，常用于钙、镁、锌等金属离子的测定。滴定需控制 pH，加入掩蔽剂消除干扰，并做空白试验校正。</p><ul><li>碘量法需避光操作，防止碘挥发和氧化。</li><li>配位滴定中金属指示剂应适当选择。</li></ul>` }
        ], refs: [] } },
      { title: '药物制剂分析与方法学验证', brief: '溶出度、含量均匀度与验证指标。',
        q: [
          { stem: '片剂溶出度测定常用的方法是：', options: ['篮法和桨法', '旋转蒸发法', '蒸馏法', '离心法'], answer: 0, explain: '溶出度测定常用篮法、桨法和小杯法等，以规定介质和转速模拟体内释放。' },
          { stem: '方法学验证中准确度常用什么表示：', options: ['回收率', '相对标准偏差', '相关系数', '检测限'], answer: 0, explain: '准确度表示测定值与真实值的接近程度，常用回收率评价。' },
          { stem: '含量均匀度检查主要适用于：', options: ['小剂量制剂', '大剂量制剂', '外用制剂', '所有注射剂'], answer: 0, explain: '小剂量制剂中药物含量低，单个制剂间差异可能较大，需检查含量均匀度。' }
        ],
        doc: { lead: '制剂分析针对不同剂型设置检查项目，方法学验证保证分析结果可靠。', sections: [
          { id: 'k1', title: '制剂分析', html: `<p>制剂分析需考虑辅料干扰、剂型特点和药物含量。片剂常需检查重量差异、崩解时限、溶出度和含量均匀度；注射剂需检查装量、可见异物、无菌和细菌内毒素。</p><p>溶出度测定常用篮法和桨法，以规定介质和转速模拟体内释放，取样后用 HPLC 或紫外法测定。溶出曲线可评价制剂质量一致性，也是生物等效性研究的重要依据。</p><ul><li>缓控释制剂需进行释放度检查。</li><li>注射剂还需检查不溶性微粒和渗透压。</li></ul>` },
          { id: 'k2', title: '方法学验证', html: `<p>分析方法验证包括专属性、准确度、精密度、线性、范围、检测限和定量限。准确度用回收率表示，精密度用相对标准偏差表示，专属性要求辅料和杂质不干扰测定。</p><p>稳定性指示方法应能区分药物与降解产物，用于稳定性试验和有效期确定。质量标准应结合药典要求和企业实际，方法变更需重新验证并进行可比性研究。</p><ul><li>验证指标应根据方法用途确定。</li><li>数据完整性是方法验证和检验的基础。</li></ul>` }
        ], refs: [] } }
    ],

    '天然药物化学': [
      { title: '糖类与苷类', brief: '糖的结构、苷键类型与 Molish 反应。',
        q: [
          { stem: '苷类水解后生成的产物是：', options: ['苷元和糖', '生物碱和糖', '蛋白质和糖', '脂肪和糖'], answer: 0, explain: '苷类由苷元与糖通过苷键连接，水解后苷键断裂，生成苷元和糖。' },
          { stem: '按苷键原子分类，最常见的苷类是：', options: ['氧苷', '硫苷', '氮苷', '碳苷'], answer: 0, explain: '氧苷由苷元羟基与糖端基碳形成苷键，是天然界最常见的苷类。' },
          { stem: 'Molish 反应可用于检识：', options: ['糖和苷类', '生物碱', '黄酮', '挥发油'], answer: 0, explain: 'Molish 反应是糖类的通用显色反应，苷类水解后含糖，也可呈阳性。' }
        ],
        doc: { lead: '糖类是生命活动的重要物质，苷类则由糖与苷元连接而成，两者在检识上联系紧密。', sections: [
          { id: 'k1', title: '糖类', html: `<p>糖类包括单糖、寡糖和多糖，单糖易溶于水、有甜味，多糖多无甜味且难溶于水。糖类可用 Molish 反应检识，与 α-萘酚和浓硫酸反应在界面形成紫色环。</p><p>多糖如淀粉、纤维素、多糖类免疫调节剂具有多种生物活性。提取多糖常用水提醇沉法，除去蛋白质和小分子杂质后干燥，可用苯酚-硫酸法测定总糖含量。</p><ul><li>单糖多具还原性，可发生银镜反应。</li><li>多糖分子量大，遇醇析出。</li></ul>` },
          { id: 'k2', title: '苷类', html: `<p>苷类是糖或糖衍生物的端基碳与苷元通过苷键连接而成的化合物，按苷键原子分为氧苷、硫苷、氮苷和碳苷。氧苷最常见，包括醇苷、酚苷、氰苷和酯苷。</p><p>苷类易被酸或酶水解，水解后生成苷元和糖，水解条件不同可得到一次苷或次级苷。检识苷类可用 Molish 反应，结合苷元的特征显色反应判断类型。</p><ul><li>提取时需注意酶的酶解作用，可先杀酶。</li><li>碳苷较难水解，需较强条件。</li></ul>` }
        ], refs: [] } },
      { title: '萜类与挥发油', brief: '异戊二烯单位、挥发油提取与代表成分。',
        q: [
          { stem: '萜类化合物的基本结构单位是：', options: ['异戊二烯', '氨基酸', '葡萄糖', '脂肪酸'], answer: 0, explain: '萜类由异戊二烯单位首尾相连构成，按单位数分为单萜、倍半萜和二萜等。' },
          { stem: '挥发油最常用的提取方法是：', options: ['水蒸气蒸馏法', '煎煮法', '醇沉法', '盐析法'], answer: 0, explain: '挥发油具有挥发性且难溶于水，水蒸气蒸馏法是最常用的提取方法。' },
          { stem: '薄荷油的主要成分是：', options: ['薄荷醇', '薄荷酮', '樟脑', '桉叶油素'], answer: 0, explain: '薄荷油的主要成分是薄荷醇，另含薄荷酮等，薄荷醇具有清凉作用。' }
        ],
        doc: { lead: '萜类由异戊二烯单位构成，挥发油则是多种挥发性成分的混合物。', sections: [
          { id: 'k1', title: '萜类', html: `<p>萜类化合物由异戊二烯单位构成，按单位数分为单萜、倍半萜、二萜和二倍半萜等。单萜多存在于挥发油中，二萜和倍半萜内酯具有显著生物活性，如青蒿素、穿心莲内酯。</p><p>萜类多具挥发性、脂溶性，易溶于有机溶剂。提取常用水蒸气蒸馏、溶剂提取和超临界 CO2 萃取，分离可用硅胶柱色谱，按极性差异洗脱。</p><ul><li>青蒿素是含过氧桥的倍半萜内酯。</li><li>紫杉醇属于二萜类化合物。</li></ul>` },
          { id: 'k2', title: '挥发油', html: `<p>挥发油是植物中具有挥发性、可随水蒸气蒸馏的油状成分，主要由萜类、芳香族和脂肪族化合物组成。提取常用水蒸气蒸馏法、压榨法和超临界 CO2 萃取法。</p><p>挥发油需检查性状、相对密度、折光率、旋光度和酸值，并测定主要成分含量。贮存应密闭、避光、阴凉，防止氧化聚合和挥发损失。</p><ul><li>挥发油易氧化聚合，应低温避光保存。</li><li>水蒸气蒸馏法设备简单，适合工业化生产。</li></ul>` }
        ], refs: [] } },
      { title: '皂苷与强心苷', brief: '泡沫试验、溶血性与强心苷显色反应。',
        q: [
          { stem: '皂苷水溶液振摇后产生：', options: ['持久泡沫', '蓝色沉淀', '银镜', '红色荧光'], answer: 0, explain: '皂苷具有表面活性，振摇后产生持久性泡沫，是其重要理化特征。' },
          { stem: '强心苷苷元结构中含有：', options: ['五元不饱和内酯环', '噻唑环', 'β-内酰胺环', '吡啶环'], answer: 0, explain: '甲型强心苷苷元 C17 位连接五元不饱和内酯环，是强心活性的重要结构。' },
          { stem: '强心苷的 Kedde 反应用于检识：', options: ['五元不饱和内酯环', '甾体母核', '糖链', '酚羟基'], answer: 0, explain: 'Kedde 反应与五元不饱和内酯环有关，可用于检识甲型强心苷。' }
        ],
        doc: { lead: '皂苷和强心苷都是苷类，前者表面活性明显，后者强心但治疗窗窄。', sections: [
          { id: 'k1', title: '皂苷', html: `<p>皂苷是苷元为三萜或甾体、糖链较多的苷类，水溶液振摇产生持久泡沫。按苷元分为三萜皂苷和甾体皂苷，人参皂苷、甘草皂苷属三萜皂苷，薯蓣皂苷属甾体皂苷。</p><p>皂苷多具溶血性，因与红细胞膜胆固醇结合改变通透性，但口服时受胃酸和肠道影响，毒性不明显。皂苷可用泡沫试验、Liebermann-Burchard 反应和溶血试验检识。</p><ul><li>皂苷常用甲醇或乙醇提取，正丁醇萃取得总皂苷。</li><li>皂苷具有表面活性，可作为乳化剂研究。</li></ul>` },
          { id: 'k2', title: '强心苷', html: `<p>强心苷由强心苷元与糖组成，苷元含甾体母核和五元不饱和内酯环，糖部分多为去氧糖。强心苷能增强心肌收缩力、减慢心率，是治疗心力衰竭的重要药物。</p><p>强心苷的显色反应包括 Kedde 反应、Keller-Kiliani 反应和 Liebermann-Burchard 反应。强心苷治疗窗窄，过量可致心律失常，需严格控制剂量并监测血药浓度。</p><ul><li>Keller-Kiliani 反应可检识去氧糖。</li><li>强心苷中毒常见室性早搏，低血钾可加重。</li></ul>` }
        ], refs: [] } },
      { title: '醌类与其他成分', brief: '蒽醌、Bornträger 反应与香豆素。',
        q: [
          { stem: '蒽醌类化合物与碱液反应显红色，这一反应称为：', options: ['Bornträger 反应', 'Molish 反应', 'Kedde 反应', '碘化铋钾反应'], answer: 0, explain: '羟基蒽醌遇碱液显红色，称为 Bornträger 反应，可用于检识蒽醌类。' },
          { stem: '大黄中具有泻下作用的有效成分主要是：', options: ['蒽醌类', '生物碱类', '皂苷类', '挥发油'], answer: 0, explain: '大黄含游离蒽醌和结合蒽醌，番泻苷等结合型蒽醌具有泻下作用。' },
          { stem: '香豆素类化合物在紫外光下通常显：', options: ['蓝色荧光', '红色沉淀', '银镜', '黄色结晶'], answer: 0, explain: '香豆素具有内酯结构，紫外光下多显蓝色荧光，可用于检识。' }
        ],
        doc: { lead: '醌类和香豆素是两类分布广泛的天然产物，颜色反应和内酯性质是鉴别要点。', sections: [
          { id: 'k1', title: '醌类', html: `<p>醌类包括苯醌、萘醌、菲醌和蒽醌，广泛分布于植物中，具有抗菌、抗肿瘤和泻下等活性。大黄中的大黄素、大黄酸属蒽醌类，是泻下和抗菌的有效成分。</p><p>蒽醌类可用 Bornträger 反应检识，与碱液反应显红色。游离蒽醌溶于有机溶剂，结合蒽醌易溶于水，提取时常用不同极性溶剂分段提取，再经柱色谱分离。</p><ul><li>游离蒽醌与结合蒽醌的溶解性差异明显。</li><li>Bornträger 反应需在碱性条件下观察颜色。</li></ul>` },
          { id: 'k2', title: '香豆素与天然药物开发', html: `<p>香豆素是顺式邻羟基桂皮酸的内酯，具芳香甜味，紫外光下多显蓝色荧光。香豆素可用异羟肟酸铁反应检识，七叶内酯、补骨脂素等具有抗菌、光敏和抗凝等活性。</p><p>天然药物开发需经过活性筛选、有效成分分离、结构鉴定和药理评价。青蒿素、紫杉醇等来源于天然产物的药物证明，天然产物是创新药物的重要来源。</p><ul><li>香豆素内酯环在碱性条件下可开环。</li><li>天然产物结构改造可改善活性和成药性。</li></ul>` }
        ], refs: [] } }
    ],

    '临床药学': [
      { title: '临床药物治疗学基础', brief: '治疗原则、循证证据与个体化给药。',
        q: [
          { stem: '制定药物治疗方案的首要步骤是：', options: ['明确诊断和适应证', '确定药品价格', '选择给药途径', '安排随访'], answer: 0, explain: '药物治疗必须以明确诊断和适应证为前提，再考虑药物选择、剂量和疗程。' },
          { stem: '循证医学中证据等级最高的研究类型是：', options: ['系统评价和随机对照试验', '病例报告', '专家意见', '动物实验'], answer: 0, explain: '系统评价和随机对照试验偏倚风险低，证据等级高于观察性研究和专家意见。' },
          { stem: '药物基因组学检测的主要目的是：', options: ['指导个体化用药', '判断药物真伪', '测定药品含量', '评价药品稳定性'], answer: 0, explain: '基因检测可识别药物代谢和靶点差异，帮助选择药物和调整剂量。' }
        ],
        doc: { lead: '临床药物治疗以患者为中心，把诊断、证据和个体差异结合起来制定方案。', sections: [
          { id: 'k1', title: '药物治疗原则', html: `<p>临床药物治疗以明确诊断和适应证为前提，综合考虑疗效、安全性、经济性和患者依从性。治疗方案应包括药物选择、剂量、给药途径、疗程和监测计划。</p><p>循证医学强调将最佳研究证据、临床经验和患者意愿结合。系统评价和随机对照试验证据等级较高，观察性研究和专家意见等级较低，选药时应优先参考高质量证据。</p><ul><li>药物治疗应遵循安全、有效、经济和适当的原则。</li><li>方案实施后需评估疗效和不良反应。</li></ul>` },
          { id: 'k2', title: '个体化给药', html: `<p>个体化给药依据患者的年龄、体重、肝肾功能、基因组和合并用药调整剂量。治疗药物监测和基因检测可帮助识别浓度异常和代谢差异，减少无效用药和毒性反应。</p><p>特殊人群如老年人、儿童、孕妇和肝肾功能不全者，药动学参数改变明显，需相应调整剂量和给药间隔。用药后应评估疗效与不良反应，及时修订方案。</p><ul><li>老年人肝肾功能下降，宜从小剂量开始。</li><li>儿童剂量常按体重或体表面积计算。</li></ul>` }
        ], refs: [] } },
      { title: '常见疾病药物治疗', brief: '高血压、糖尿病与冠心病的用药方案。',
        q: [
          { stem: '2 型糖尿病的一线治疗药物是：', options: ['二甲双胍', '胰岛素', '磺脲类', 'α-葡萄糖苷酶抑制剂'], answer: 0, explain: '二甲双胍降糖有效、低血糖风险小，是 2 型糖尿病初治的一线用药。' },
          { stem: '高血压合并糖尿病和蛋白尿的患者首选：', options: ['ACEI 或 ARB', '噻嗪类利尿药', 'β 受体阻断药', 'α 受体阻断药'], answer: 0, explain: 'ACEI 或 ARB 可降低尿蛋白、保护肾功能，是合并糖尿病和蛋白尿患者的首选。' },
          { stem: '急性冠脉综合征常用的抗血小板方案是：', options: ['阿司匹林联合氯吡格雷', '单用华法林', '单用肝素', '单用尿激酶'], answer: 0, explain: '阿司匹林联合 P2Y12 受体抑制剂构成双联抗血小板治疗，用于预防血栓事件。' }
        ],
        doc: { lead: '常见慢病治疗强调达标、联合和长期管理，方案应结合合并症和耐受性。', sections: [
          { id: 'k1', title: '心血管疾病', html: `<p>高血压治疗常用 ACEI、ARB、钙通道阻滞药、利尿药和 β 受体阻断药，合并糖尿病或蛋白尿者优先选择 ACEI 或 ARB。冠心病需抗血小板、调脂和抗心绞痛治疗。</p><p>心力衰竭治疗包括利尿药、ACEI/ARB、β 受体阻断药、醛固酮受体拮抗剂和 SGLT2 抑制剂。用药应从低剂量起始，逐步滴定至目标剂量，并监测血压、心率和肾功能。</p><ul><li>ACEI 与 ARB 不宜联合使用。</li><li>冠心病二级预防需长期使用他汀类。</li></ul>` },
          { id: 'k2', title: '内分泌疾病', html: `<p>2 型糖尿病一线用药为二甲双胍，合并动脉粥样硬化性心血管疾病或心衰者可优先选用 SGLT2 抑制剂或 GLP-1 受体激动剂。胰岛素用于口服药控制不佳或急性并发症。</p><p>甲状腺功能亢进常用甲巯咪唑或丙硫氧嘧啶，需监测血常规和肝功能；甲状腺功能减退用左甲状腺素替代，剂量需根据 TSH 调整，老年人和冠心病患者应从小剂量开始。</p><ul><li>二甲双胍在肾功能不全者需减量或停用。</li><li>左甲状腺素宜空腹服用，避免与钙铁同服。</li></ul>` }
        ], refs: [] } },
      { title: '抗菌药物临床应用', brief: '经验治疗、分级管理与特殊人群。',
        q: [
          { stem: '抗菌药物经验治疗前最重要的步骤是：', options: ['留取标本做病原学检查', '立即联合用药', '加大剂量', '预防性使用'], answer: 0, explain: '经验治疗前留取标本做培养和药敏，可为后续目标治疗提供依据。' },
          { stem: '使用青霉素前必须进行：', options: ['皮肤过敏试验', '肝功能检查', '肾功能检查', '眼科检查'], answer: 0, explain: '青霉素可致严重过敏反应，用药前必须做皮肤过敏试验并备好急救药品。' },
          { stem: '我国抗菌药物分级管理分为：', options: ['非限制使用、限制使用、特殊使用三级', '一级、二级、三级', '甲类、乙类、丙类', '处方药和非处方药'], answer: 0, explain: '抗菌药物按安全性、疗效、细菌耐药性和价格分为非限制使用、限制使用和特殊使用三级。' }
        ],
        doc: { lead: '抗菌药物临床应用的核心是明确指征、病原导向和分级管理。', sections: [
          { id: 'k1', title: '合理用药原则', html: `<p>抗菌药物应用应明确适应证，经验治疗前留取标本做培养和药敏。选药需考虑病原菌、感染部位、药物分布和患者肝肾功能，避免无指征使用和频繁换药。</p><p>联合用药适用于病原未明的重症感染、混合感染和结核等需长期治疗的疾病。用药疗程应足够，但不宜过长，以减少耐药和不良反应。</p><ul><li>病毒性感冒不应常规使用抗菌药物。</li><li>预防用药应严格掌握指征和疗程。</li></ul>` },
          { id: 'k2', title: '分级管理与特殊人群', html: `<p>我国对抗菌药物实行分级管理，分为非限制使用、限制使用和特殊使用三级，特殊使用级需经会诊和审批。医疗机构应建立抗菌药物临床应用监测和细菌耐药预警机制。</p><p>特殊人群使用抗菌药物需调整剂量，如肾功能不全者减少氨基糖苷类，孕妇禁用喹诺酮类和四环素类。用药期间监测疗效、不良反应和菌群失调。</p><ul><li>特殊使用级抗菌药物不得在门诊使用。</li><li>长期使用广谱抗菌药需警惕二重感染。</li></ul>` }
        ], refs: [] } },
      { title: '药物基因组学与精准用药', brief: '基因多态性、靶向治疗与个体化方案。',
        q: [
          { stem: 'CYP2C19 慢代谢者使用氯吡格雷可能出现：', options: ['抗血小板作用减弱', '出血风险显著增加', '血糖升高', '肝功能衰竭'], answer: 0, explain: '氯吡格雷需经 CYP2C19 活化，慢代谢者活性代谢物生成减少，抗血小板作用减弱。' },
          { stem: 'HLA-B*5701 阳性者禁用：', options: ['阿巴卡韦', '阿司匹林', '二甲双胍', '青霉素'], answer: 0, explain: 'HLA-B*5701 阳性者使用阿巴卡韦易发生严重超敏反应，用药前应筛查并禁用。' },
          { stem: '华法林的剂量调整与下列哪些基因型相关：', options: ['CYP2C9 和 VKORC1', 'CYP2D6 和 OPRM1', 'HLA-B 和 HLA-C', 'EGFR 和 ALK'], answer: 0, explain: 'CYP2C9 影响华法林代谢，VKORC1 影响靶点敏感性，二者共同影响剂量需求。' }
        ],
        doc: { lead: '药物基因组学把基因差异转化为用药依据，是精准用药的重要组成。', sections: [
          { id: 'k1', title: '药物基因组学', html: `<p>药物基因组学研究基因多态性对药物吸收、代谢、转运和靶点的影响。CYP2C19 慢代谢者使用氯吡格雷时活性代谢物生成减少，抗血小板作用减弱，可考虑替代药物。</p><p>HLA-B*5701 阳性者使用阿巴卡韦易发生严重超敏反应，用药前应筛查；CYP2C9 和 VKORC1 基因型影响华法林剂量，结合基因检测可提高抗凝治疗的安全性。</p><ul><li>基因多态性可改变酶活性、转运体功能和受体敏感性。</li><li>基因检测结果需结合临床和药物浓度综合解读。</li></ul>` },
          { id: 'k2', title: '精准用药', html: `<p>精准用药将基因检测、治疗药物监测和临床资料结合，制定个体化给药方案。肿瘤靶向治疗需检测驱动基因突变，如 EGFR 突变肺癌选用相应酪氨酸激酶抑制剂。</p><p>基因检测应遵循知情同意和隐私保护原则，结果解读需结合药物代谢表型和临床实际。检测不能替代疗效监测，用药后仍需评估反应并调整方案。</p><ul><li>靶向治疗前应明确分子靶点。</li><li>基因检测应选择经过验证的方法和平台。</li></ul>` }
        ], refs: [] } }
    ],

    '药事管理学': [
      { title: '药品管理法与法规体系', brief: '药品定义、上市许可与监管职责。',
        q: [
          { stem: '我国药品管理的基本法律是：', options: ['《药品管理法》', '《药品管理法实施条例》', '《药品注册管理办法》', '《中国药典》'], answer: 0, explain: '《药品管理法》是我国药品管理的基本法律，其他法规和规章以其为依据。' },
          { stem: '药品上市许可持有人对药品的什么负责：', options: ['全生命周期的安全性、有效性和质量可控性', '仅生产环节', '仅销售环节', '仅研发环节'], answer: 0, explain: '上市许可持有人对药品研制、生产、经营和使用全过程依法承担责任。' },
          { stem: '我国对疫苗实行：', options: ['最严格的管理制度', '与普通药品相同的管理', '备案管理', '企业自律管理'], answer: 0, explain: '疫苗关系公共卫生安全，我国对疫苗实行最严格的管理制度并建立全程追溯体系。' }
        ],
        doc: { lead: '药品管理法确立药品监管的基本制度，上市许可持有人对药品全生命周期负责。', sections: [
          { id: 'k1', title: '法规体系', html: `<p>我国药品管理法规体系以《药品管理法》为核心，包括行政法规、部门规章和规范性文件。《药品管理法》规定药品研制、生产、经营、使用和监督管理的基本要求。</p><p>药品上市许可持有人制度明确持有人对药品全生命周期的安全性、有效性和质量可控性负责。持有人可自行生产或委托生产，但需签订质量协议并实施全程管理。</p><ul><li>药品注册标准不得低于国家药品标准。</li><li>持有人应建立药物警戒和追溯体系。</li></ul>` },
          { id: 'k2', title: '监管体系与特殊药品', html: `<p>药品监督管理部门按国家、省、市、县分级负责药品监管。国家药监局负责药品注册和重大监管事项，省级药品监管部门负责生产许可和日常监管，市县负责经营和使用环节监管。</p><p>疫苗实行最严格的管理制度，疫苗上市许可持有人和接种单位应建立全程追溯体系。麻醉药品、精神药品、毒性药品和放射性药品实行特殊管理，严格控制生产、流通和使用。</p><ul><li>特殊管理药品实行定点生产、定点经营。</li><li>疫苗储存运输需符合温度控制要求。</li></ul>` }
        ], refs: [] } },
      { title: '药品价格与医保管理', brief: '集中采购、医保目录与支付方式。',
        q: [
          { stem: '国家医保药品目录调整原则上：', options: ['每年一次', '每五年一次', '每十年一次', '不调整'], answer: 0, explain: '国家医保药品目录实行动态调整，原则上每年进行一次。' },
          { stem: '药品集中带量采购的主要目的是：', options: ['降低药品虚高价格', '提高药品价格', '增加药品品种', '放宽质量要求'], answer: 0, explain: '集中带量采购以约定采购量换取价格下降，降低药品虚高价格并保证供应。' },
          { stem: '医保药品目录中甲类药品的特点是：', options: ['费用全额纳入报销范围', '需个人先自付一定比例', '不予报销', '仅限住院使用'], answer: 0, explain: '甲类药品费用全额纳入医保报销范围，乙类药品需个人先自付一定比例。' }
        ],
        doc: { lead: '药品价格和医保政策影响药品可及性，集中采购和目录谈判是重要调控手段。', sections: [
          { id: 'k1', title: '价格管理', html: `<p>药品价格管理实行市场调节价为主，部分药品实行政府指导价或政府定价。集中带量采购通过以量换价降低药品虚高价格，中选药品应保证质量和供应。</p><p>药品价格监测和成本调查可发现异常价格行为，防止垄断和价格欺诈。医疗机构应执行药品零差率政策，规范药品购销行为，减轻患者负担。</p><ul><li>集中采购中选企业应保障质量和供应。</li><li>短缺药品可通过监测和储备保障供应。</li></ul>` },
          { id: 'k2', title: '医保管理', html: `<p>国家医保药品目录分为甲类和乙类，甲类费用全额纳入报销范围，乙类需个人先自付一定比例。目录调整原则上每年一次，通过谈判将新药、好药纳入报销范围。</p><p>医保谈判药品实行协议期内价格，医疗机构应按规定配备和合理使用。医保支付方式改革推行按病种付费和 DRG/DIP，促进合理用药和费用控制。</p><ul><li>谈判药品可通过双通道在定点医院和药店购买。</li><li>医保支付标准与药品价格和疗效相关。</li></ul>` }
        ], refs: [] } },
      { title: '药品知识产权与研发管理', brief: '专利、数据保护与中药品种保护。',
        q: [
          { stem: '我国发明专利的保护期一般为：', options: ['20 年', '10 年', '5 年', '50 年'], answer: 0, explain: '我国发明专利保护期为 20 年，自申请日起计算。' },
          { stem: '药品试验数据保护制度主要保护：', options: ['创新药申请人提交的试验数据', '药品包装设计', '药品广告', '药品价格'], answer: 0, explain: '试验数据保护给予创新药一定期限的数据独占权，防止仿制药直接依赖其数据申报。' },
          { stem: '中药品种保护制度的目的之一是：', options: ['鼓励中药创新并保护特定品种', '限制中药生产', '取消中药注册', '统一中药价格'], answer: 0, explain: '中药品种保护对特定企业生产的中药品种给予保护，鼓励中药创新和质量提升。' }
        ],
        doc: { lead: '药品知识产权保护创新，研发管理则保证研究过程规范和数据可靠。', sections: [
          { id: 'k1', title: '知识产权', html: `<p>药品知识产权包括专利、商标、商业秘密和试验数据保护。发明专利保护期一般为 20 年，药品专利可涉及化合物、制剂、用途和制备方法，仿制药上市前需处理专利问题。</p><p>药品试验数据保护给予创新药一定期限的数据独占权，在此期间仿制药申请人不得依赖其数据申报。中药品种保护制度对特定中药品种给予保护，鼓励中药创新。</p><ul><li>专利链接制度可协调创新药和仿制药的利益。</li><li>商业秘密保护需建立保密制度和协议。</li></ul>` },
          { id: 'k2', title: '研发管理', html: `<p>药物研发投入大、周期长、风险高，企业应建立项目管理体系，合理配置资源。研发过程需遵守 GLP、GCP 和 GMP 要求，确保数据真实、完整和可追溯。</p><p>技术转让和委托研发应签订合同，明确知识产权归属、质量责任和风险分担。药品注册申报需提交完整的研究资料，接受药品监管部门的审评和核查。</p><ul><li>研发立项应进行市场、技术和法规评估。</li><li>注册核查发现数据造假将依法处理。</li></ul>` }
        ], refs: [] } },
      { title: '药品安全监管与法律责任', brief: '假劣药、召回与执业药师责任。',
        q: [
          { stem: '药品召回中一级召回的启动时限是：', options: ['24 小时内', '48 小时内', '72 小时内', '7 日内'], answer: 0, explain: '一级召回针对可能引起严重健康危害的药品，应在 24 小时内启动召回。' },
          { stem: '生产、销售假药可能承担的法律责任包括：', options: ['行政责任、民事责任和刑事责任', '仅行政责任', '仅民事责任', '仅道德责任'], answer: 0, explain: '生产销售假药可能同时承担行政责任、民事赔偿责任，构成犯罪的依法追究刑事责任。' },
          { stem: '药品不良反应报告中，严重不良反应应在多久内报告：', options: ['15 日内', '30 日内', '60 日内', '90 日内'], answer: 0, explain: '严重药品不良反应应在 15 日内报告，死亡病例还需及时报告。' }
        ],
        doc: { lead: '药品安全监管覆盖全生命周期，法律责任是保障公众用药安全的底线。', sections: [
          { id: 'k1', title: '安全监管', html: `<p>药品安全监管覆盖研发、生产、经营和使用全过程。假药指成分与国家药品标准不符或冒充药品的情形，劣药指成分含量不符合标准或超过有效期等情形，二者法律责任不同。</p><p>药品召回按风险程度分为一级、二级和三级，一级召回应在 24 小时内启动并通知相关单位。持有人应主动收集不良反应信息，开展风险评价并采取控制措施。</p><ul><li>药品追溯体系可实现来源可查、去向可追。</li><li>药物警戒贯穿药品全生命周期。</li></ul>` },
          { id: 'k2', title: '法律责任', html: `<p>违反药品管理法规的法律责任包括行政责任、民事责任和刑事责任。生产销售假药可构成犯罪，依法追究刑事责任；造成患者损害的，应承担赔偿责任。</p><p>执业药师应依法注册、履职，对处方审核和用药指导负责。违反职业道德和法规的，可受到警告、罚款、吊销执业证书等处罚，情节严重的追究刑事责任。</p><ul><li>严重不良反应应在 15 日内报告。</li><li>执业药师应对处方进行审核，发现不合理用药及时沟通。</li></ul>` }
        ], refs: [] } }
    ],

    '毕业实习与职业发展': [
      { title: '医院药学实习', brief: '调剂四查十对、药品储存与静脉调配。',
        q: [
          { stem: '静脉药物配置中心调配药物时应执行：', options: ['双人核对', '单人操作无需核对', '仅核对药品名称', '仅核对患者姓名'], answer: 0, explain: '静脉药物配置风险高，应执行双人核对，核对药品、剂量、溶媒和患者信息。' },
          { stem: '医院药库阴凉库的温度要求是：', options: ['不高于 20 ℃', '不高于 30 ℃', '2～8 ℃', '-20 ℃以下'], answer: 0, explain: '阴凉库温度不高于 20 ℃，冷藏药品保存在 2～8 ℃，常温为 10～30 ℃。' },
          { stem: '门诊发药时药师应重点交代：', options: ['用法用量和注意事项', '药品价格', '药品广告', '医师职称'], answer: 0, explain: '发药时应交代用法、用量、服药时间和主要注意事项，确保患者正确用药。' }
        ],
        doc: { lead: '医院药学实习从调剂、储存到静脉用药调配，强调规范操作和患者安全。', sections: [
          { id: 'k1', title: '调剂与静脉调配', html: `<p>医院药学实习包括门诊调剂、住院调剂、静脉药物配置和药库管理。调剂应执行四查十对，核对处方合法性、药品名称、规格、数量和用法，发药时交代注意事项。</p><p>静脉药物配置中心应在洁净环境下集中调配，严格执行无菌操作和双人核对，防止微生物污染和配伍差错。危害药品调配需使用生物安全柜并做好职业防护。</p><ul><li>四查十对是调剂工作的基本规范。</li><li>细胞毒性药物调配需做好职业暴露防护。</li></ul>` },
          { id: 'k2', title: '药库与养护', html: `<p>药库管理包括采购、验收、储存和养护。药品应按温湿度要求分区存放，阴凉库不高于 20 ℃，冷藏药品保存在 2～8 ℃，特殊管理药品双人双锁。</p><p>药品效期管理遵循先进先出、近效期先出原则，定期盘点并处理过期药品。发现质量问题应立即封存、报告，配合调查并做好记录。</p><ul><li>药品应按批号堆码，保持适当间距。</li><li>温湿度应每日监测并记录。</li></ul>` }
        ], refs: [] } },
      { title: '药品检验与质量控制实习', brief: '取样、HPLC 操作与数据完整性。',
        q: [
          { stem: '药品检验原始记录的要求是：', options: ['真实、完整、可追溯', '只记录合格结果', '可事后修改', '可选择性剔除'], answer: 0, explain: '原始记录应真实、完整、及时、可追溯，不得事后补记或选择性剔除数据。' },
          { stem: '高效液相色谱仪进样前应：', options: ['排气泡并平衡色谱柱', '直接进样', '关闭检测器', '拆下色谱柱'], answer: 0, explain: '进样前应排除流动相气泡并平衡色谱柱，待基线稳定后再进样。' },
          { stem: '标准品和对照品应：', options: ['按说明书规定条件储存', '随意放置在窗台', '与样品混放', '冷冻所有品种'], answer: 0, explain: '标准品和对照品应按说明书规定的温度、避光和干燥条件储存，并记录使用情况。' }
        ],
        doc: { lead: '药品检验实习帮助掌握取样、检验和记录的全过程，数据完整性是质量控制的底线。', sections: [
          { id: 'k1', title: '取样与检验', html: `<p>药品检验实习应掌握取样、检验和记录的全过程。取样应具有代表性，按批号和包装数量确定取样件数，检验按药典方法和标准操作规程进行。</p><p>检验项目包括性状、鉴别、检查和含量测定，结果应与质量标准比较并作出判定。不合格样品应复检并调查原因，检验报告应真实、完整、可追溯。</p><ul><li>取样工具应清洁、干燥，避免污染样品。</li><li>检验原始记录不得撕毁或涂改。</li></ul>` },
          { id: 'k2', title: '仪器与记录', html: `<p>高效液相色谱仪使用前应排气泡、平衡色谱柱，进样前确认流动相和检测器状态。测定完成后应冲洗色谱柱，记录仪器使用和维护情况，保证数据完整。</p><p>标准品和对照品应按说明书条件储存，使用时准确称量并记录批号。实验室应建立数据完整性管理，禁止修改原始数据和选择性剔除结果。</p><ul><li>色谱数据应可追溯，审计追踪应开启。</li><li>仪器故障和异常应记录并评估影响。</li></ul>` }
        ], refs: [] } },
      { title: '药物研发与生产实习', brief: '实验记录、洁净区管理与工艺验证。',
        q: [
          { stem: '进入 GMP 洁净区前应：', options: ['按更衣程序穿戴洁净服', '直接进入', '只换鞋', '只戴口罩'], answer: 0, explain: '进入洁净区应按更衣程序穿戴洁净服，经过气闸或缓冲间，防止污染。' },
          { stem: '批生产记录应：', options: ['随生产同步填写', '生产结束后补写', '由他人代写', '随意修改'], answer: 0, explain: '批生产记录应随生产同步填写，内容真实、完整，不得事后补写或随意修改。' },
          { stem: '工艺验证的目的是：', options: ['证明工艺能稳定生产出符合质量要求的产品', '提高产品价格', '减少生产人员', '替代质量检验'], answer: 0, explain: '工艺验证通过连续批次证明工艺在设定参数下能稳定生产出符合质量标准的产品。' }
        ],
        doc: { lead: '研发与生产实习帮助理解药品从实验室到车间的转化，规范记录和洁净管理是核心。', sections: [
          { id: 'k1', title: '研发实习', html: `<p>药物研发实习可在合成、制剂或分析岗位进行，参与文献调研、实验设计和数据处理。实验记录应及时、真实、完整，写明条件、现象和结果，不得事后补记或涂改。</p><p>研发过程需关注知识产权和实验室安全，危险试剂应按规范储存和使用。阶段性成果应进行总结和汇报，培养独立思考和解决问题的能力。</p><ul><li>实验记录应使用不褪色墨水笔书写并签名。</li><li>危险反应应在通风橱内进行。</li></ul>` },
          { id: 'k2', title: '生产实习', html: `<p>药品生产实习应熟悉洁净区管理，人员进入需按更衣程序穿戴洁净服，操作遵守人流、物流分开原则。生产批记录应随生产同步填写，不得提前或事后填写。</p><p>工艺验证和清洁验证是保证产品质量的重要手段，偏差和变更需按程序处理并评估影响。实习生应在带教老师指导下操作，不得擅自独立操作关键设备。</p><ul><li>洁净区行为应避免快速走动和大幅动作。</li><li>偏差处理应先记录、评估，再调查原因。</li></ul>` }
        ], refs: [] } },
      { title: '毕业论文与科研训练', brief: '选题、文献检索、实验设计与论文写作。',
        q: [
          { stem: '药物化学论文选题应优先考虑：', options: ['科学性、可行性和一定创新性', '题目越大越好', '与专业无关的热点', '无需文献调研'], answer: 0, explain: '选题应结合专业方向，具备科学性、可行性和一定创新性，并能在规定时间内完成。' },
          { stem: '文献检索常用的中文数据库是：', options: ['中国知网', 'PubMed', 'Web of Science', 'Scopus'], answer: 0, explain: '中国知网是常用的中文文献数据库，PubMed、Web of Science 和 Scopus 以英文文献为主。' },
          { stem: '实验数据的正确处理方式是：', options: ['完整记录并如实分析', '只保留符合预期的数据', '随意修改异常值', '删除失败实验'], answer: 0, explain: '实验数据应完整记录、如实分析，选择性剔除或篡改数据属于学术不端。' }
        ],
        doc: { lead: '毕业论文训练综合运用文献、实验和写作能力，学术规范贯穿始终。', sections: [
          { id: 'k1', title: '选题与文献', html: `<p>毕业论文选题应结合专业方向，具有科学性、可行性和一定创新性。选题前应查阅文献，了解研究现状和存在问题，明确研究目的、内容和预期成果。</p><p>文献检索可利用中国知网、PubMed 和 Web of Science 等数据库，通过关键词、主题词和引文追踪获取资料。文献管理工具可帮助整理和引用，避免抄袭和格式错误。</p><ul><li>选题范围不宜过大，应能在限定时间内完成。</li><li>引用文献应忠实原文并标注出处。</li></ul>` },
          { id: 'k2', title: '实验与写作', html: `<p>实验设计应设置合理对照、重复和随机化，选择适当的统计方法。实验数据应完整记录，统计分析前检查数据分布和异常值，显著性水平常取 P 小于 0.05。</p><p>论文写作一般包括摘要、前言、材料与方法、结果、讨论和参考文献。结论应基于数据，不得夸大或篡改；引用他人成果需注明出处，遵守学术规范。</p><ul><li>结果与讨论应区分事实和推测。</li><li>论文需按学校格式要求排版和提交。</li></ul>` }
        ], refs: [] } }
    ]
  };

  var ci = 0;
  Object.keys(ov).forEach(function (stage) {
    ov[stage].modules.forEach(function (mod) {
      var extras = EXTRA[mod.name];
      if (extras) {
        extras.forEach(function (ch) {
          var idx = mod.levels.length;
          DOCS[MAJOR + '-m' + ci + '-l' + idx] = ch.doc;
          mod.levels.push({
            name: '第 ' + (idx + 1) + ' 章 · ' + ch.title,
            brief: ch.brief,
            questions: ch.q,
            ready: true
          });
        });
      }
      ci++;
    });
  });
})();
